	"A K T I V": "A C T I V",
	"A pod rzekami magmy Pyrrhosa bije Serce Roju": "And beneath the magma rivers of Pyrrhos beats the Heart of the Swarm",
	"A pod rzekami magmy Pyrrhosa bije Serce Roju. Uciszysz je — albo pogranicze stanie się jego gniazdem.": "And beneath the magma rivers of Pyrrhos beats the Heart of the Swarm. Silence it — or the Frontier will become its nest.",
	"Adm": "Adm",
	"ADM": "ADM",
	"Adm. Selen Vok": "Adm. Selen Vok",
	"ADM. SELEN VOK · ADMIRALICJA": "ADM. SELEN VOK · ADMIRALTY",
	"Adm. Vok dowodzi flotą rozejmu.": "Adm. Vok commands the truce fleet.",
	"Adm. Vok podpisała pokój, którego kiedyś nie uznała.": "Adm. Vok signed a peace she had once refused to recognise.",
	"Admiralicja": "Admiralty",
	"ADMIRALICJA": "ADMIRALTY",
	"ADMIRALICJA · NIE ISTNIEJE": "ADMIRALTY · NO LONGER EXISTS",
	"ADMIRALICJA · VOK": "ADMIRALTY · VOK",
	"Admiralicja Dominium": "Dominion Admiralty",
	"Admiralicja Dominium nie uznała rozejmu Varna": "The Dominion Admiralty did not recognise Varn's truce",
	"Admiralicja Dominium nie uznała rozejmu Varna. Flota adm. Selen Vok zamknęła orbitę Eos, zajęła doki naszej stoczni i odcięła Kolonie od pogranicza. Przełam blokadę — z ocalałej floty powstaną kapsuły desantowe dla lądowania na Eos.": "The Dominion Admiralty did not recognise Varn's truce. Adm. Selen Vok's fleet has sealed Eos orbit, seized our shipyard's docks and cut the Colonies off from the Frontier. Break the blockade — the surviving fleet will provide drop pods for the landing on Eos.",
	"Admiralicja dotrzymuje słowa": "The Admiralty keeps its word",
	"Admiralicja dotrzymuje słowa. Moje okręty lecą z wami do Bramy.": "The Admiralty keeps its word. My ships fly with you to the Gate.",
	"Admiralicja nazywa mnie zdrajcą": "The Admiralty calls me a traitor",
	"Admiralicja nazywa mnie zdrajcą. Niech więc zdrajca przyśle wam fregatę — jest już w drodze.": "The Admiralty calls me a traitor. So let the traitor send you a Frigate — it's already on its way.",
	"Admiralicja nie istnieje": "The Admiralty is no more",
	"Admiralicja nie istnieje — zamiast jej floty masz 600 metalu z jej magazynów": "The Admiralty is no more — instead of its fleet you get 600 metal from its stores",
	"Admiralicja nie istnieje — zamiast jej floty masz 600 metalu z jej magazynów.": "The Admiralty is no more — instead of its fleet you get 600 metal from its stores.",
	"Admiralicja nie istnieje; Kolonie wracają z Erebusa jako jedyna siła pogranicza.": "The Admiralty is no more; the Colonies return from Erebus as the only power of the Frontier.",
	"Admiralicja nie istnieje. Kolonie wracają z Erebusa jako jedyna siła pogranicza.": "The Admiralty is no more. The Colonies return from Erebus as the Frontier's sole power.",
	"Admiralicja opuszcza Nivalis": "The Admiralty is leaving Nivalis",
	"Admiralicja opuszcza Nivalis. Do zobaczenia przy Bramie, Kolonie.": "The Admiralty is leaving Nivalis. See you at the Gate, Colonies.",
	"Admiralicja przestała istnieć": "The Admiralty is no more",
	"Admiralicja przestała istnieć. Jej magazyny są nasze — ale do Bramy lecimy sami.": "The Admiralty is no more. Its stores are ours — but we fly to the Gate alone.",
	"Admiralicja przeszła do historii": "The Admiralty has passed into history",
	"Admiralicja przeszła do historii.": "The Admiralty has passed into history.",
	"Admiralicja traci kolejną pozycję": "The Admiralty loses another position",
	"Admiralicja traci kolejną pozycję. Vok cofa się, a szczeliny wciąż się otwierają.": "The Admiralty loses another position. Vok falls back, but the rifts keep opening.",
	"Admiralicja wycofała się do Twierdzy — bastionu za murem z dwiema bramami na końcu Popielnego Szlaku: wieże, patrole i eskorty": "The Admiralty has withdrawn to the Fortress — a bastion behind a wall with two gates at the end of the Ash Trail: towers, patrols and escorts",
	"Admiralicja wycofała się do Twierdzy — bastionu za murem z dwiema bramami na końcu Popielnego Szlaku: wieże, patrole i eskorty. Kolonie zajęły opuszczony bastion po drugiej stronie. Na szlaku stoi opuszczona stacja uplink — technik z Eos uruchomi ją, jeśli dotrze żywy. W ruinach pod popiołem otwierają się szczeliny, a Wartownicy biją we wszystkich.": "The Admiralty has withdrawn to the Fortress — a bastion behind a wall with two gates at the end of the Ash Trail: towers, patrols and escorts. The Colonies have taken an abandoned bastion on the other side. On the trail stands an abandoned uplink station — a technician from Eos will bring it online if he arrives alive. In the ruins beneath the ash, rifts are opening, and the Wardens strike at everyone.",
	"Admiralicji nie było już przy stole": "The Admiralty no longer had a seat at the table",
	"Admiralicji nie było już przy stole.": "The Admiralty no longer had a seat at the table.",
