	"Archipelag Thalassy": "Thalassa Archipelago",
	"Archiwum": "Archive",
	"Archiwum mamy przy sobie": "We have the archive with us",
	"Archiwum mamy przy sobie. Ale jamy… one żyją. Omijajcie je, jeśli zdołacie.": "We have the archive with us. But the pits… they're alive. Avoid them if you can.",
	"Archiwum otwarte": "The archive is open",
	"Archiwum otwarte. Blackout nie był awarią — Dominium chciało nas zmusić do kapitulacji.": "The archive is open. The blackout was no failure — the Dominion wanted to force us to surrender.",
	"Archiwum pod lodem": "Archive Beneath the Ice",
	"Archiwum potwierdza: te rdzenie zasilą całą sieć": "The archive confirms it: these cores will power the whole network",
	"Archiwum potwierdza: te rdzenie zasilą całą sieć. Nie możemy stracić więcej niż jednego.": "The archive confirms it: these cores will power the whole network. We can't lose more than one.",
	"Archiwum sondy": "Probe Archive",
	"ARCHIWUM SONDY": "PROBE ARCHIVE",
	"Archiwum sondy kryło ślad: blokadę zasila coś daleko w pograniczu — coś, co wysysa energię całej planety": "The probe archive held a lead: the blockade is fed by something deep in the Frontier — something draining a whole planet's energy",
	"Archiwum sondy kryło ślad: blokadę zasila coś daleko w pograniczu — coś, co wysysa energię całej planety.": "The probe archive held a lead: the blockade is fed by something deep in the Frontier — something draining a whole planet's energy.",
	"Archiwum Światła": "Archive of Light",
	"Archiwum ujawniło plan blokady": "The Archive has revealed the blockade plan",
	"Archiwum ujawniło plan blokady. Klucz jest bezpieczny; teraz flota może dotrzeć do centralnego węzła na Nadirze.": "The Archive has revealed the blockade plan. The key is safe; now the fleet can reach the central node on Nadir.",
	"Archiwum wskazało, gdzie Dominium ukryło rdzenie energetyczne dawnej sieci": "The Archive has revealed where the Dominion hid the energy cores of the old network",
	"Archiwum wskazało, gdzie Dominium ukryło rdzenie energetyczne dawnej sieci. Trzy konwojowce muszą przejść przez lodową przełęcz do latarni Kestrel. Konwój jedzie sam; Ty utrzymujesz postoje, naprawiasz pojazdy i odpierasz napady w śnieżycach.": "The Archive has revealed where the Dominion hid the energy cores of the old network. Three Core Convoys must cross the icy pass to the Kestrel lighthouse. The convoy drives on its own; you hold the stops, repair the vehicles and fight off raids in the blizzards.",
	"ARCHIWUM ZAPISÓW / PAMIĘĆ LOKALNA": "SAVE ARCHIVE / LOCAL STORAGE",
	"ARCHIWUM ZAPISÓW / POTWIERDZENIE": "SAVE ARCHIVE / CONFIRMATION",
