	"Arsenał cytadeli": "Citadel Arsenal",
	"Artefakt": "Artifact",
	"ARTEFAKT": "ARTIFACT",
	"Artefakt leży w miejscu najdalszym od baz, strzeżony przez faunę": "The artifact lies at the point farthest from the bases, guarded by fauna",
	"Artefakt leży w miejscu najdalszym od baz, strzeżony przez faunę. Jednostka naziemna podnosi go w": "The artifact lies at the point farthest from the bases, guarded by fauna. A ground unit picks it up in",
	"Artefakt na orbicie odpowiada na jakiś sygnał… To nie Rój": "The artifact in orbit is answering some signal… It's not the Swarm",
	"Artefakt na orbicie odpowiada na jakiś sygnał… To nie Rój. To coś innego.": "The artifact in orbit is answering some signal… It's not the Swarm. It's something else.",
	"Artefakt niesie:": "Artifact carried by:",
	"ARTEFAKT OBCYCH": "ALIEN ARTIFACT",
	"Artefakt obcych dotarł do centrum dowodzenia": "The alien artifact has reached the Command Centre",
	"Artefakt obcych dotarł do centrum dowodzenia. Badacze Twojej strony przejmują znalezisko.": "The alien artifact has reached the Command Centre. Your side's researchers take charge of the find.",
	"Artefakt w centrum dowodzenia — ekspedycja zakończona sukcesem": "Artifact at the Command Centre — expedition successful",
	"Artefakt w centrum dowodzenia — ekspedycja zakończona sukcesem.": "Artifact at the Command Centre — expedition successful.",
	"Artefakt w naszych rękach! Prowadź niosącego do centrum": "The artifact is in our hands! Lead the bearer to the Centre",
	"Artefakt w naszych rękach! Prowadź niosącego do centrum.": "The artifact is in our hands! Lead the bearer to the Centre.",
	"ARTEFAKTY": "ARTIFACTS",
	"Artefakty milczały od upadku Serca Roju": "The artifacts had been silent since the Heart of the Swarm fell",
	"Artefakty milczały od upadku Serca Roju. Teraz jeden z nich odpowiada — na sygnał, którego nikt nie zna.": "The artifacts had been silent since the Heart of the Swarm fell. Now one of them is answering — a signal no one knows.",
	"Artefakty od tygodnia pulsują w jednym rytmie": "For a week the artifacts have been pulsing to a single rhythm",
	"Artefakty od tygodnia pulsują w jednym rytmie. Ten na Lumerii jest najbliżej — i coś go pilnuje.": "For a week the artifacts have been pulsing to a single rhythm. The one on Lumeria is the closest — and something is guarding it.",
	"Artyleria": "Artillery",
	"artyleria o zasięgu 380; wyładowanie przeskakuje na 2 kolejne wrogie cele w promieniu 110, za każdym razem o połowę słabsze. Groźny dla zbitej piechoty.": "artillery with a range of 380; the discharge jumps to 2 more enemy targets within 110, half as strong each time. Dangerous to bunched-up infantry.",
	"artyleria; wyładowanie przeskakuje na 2 kolejnych wrogów w pobliżu (60% i 36% siły).": "artillery; the discharge jumps to 2 more nearby enemies (60% and 36% strength).",
