	"Atak w marszu": "Attack-move",
	"atak w marszu ·": "attack-move ·",
	"Atak w marszu: wskaż cel prawym przyciskiem myszy": "Attack-move: pick a target with the right mouse button",
	"Atak w marszu: wskaż cel prawym przyciskiem myszy.": "Attack-move: pick a target with the right mouse button.",
	"Atmosfera 3D: mgła w dolinach, smugi słońca": "3D atmosphere: valley mist, sun rays",
	"AUREK": "AUREK",
	"Automatyczna jakość — plansza 3D upraszcza najdroższe efekty, gdy liczba klatek spada, i przywraca je, gdy jest zapas": "Automatic quality — the 3D board simplifies its costliest effects when the frame rate drops, and brings them back when there is room",
	"Automatyczna jakość: grafika uproszczona (stopień": "Automatic quality: graphics simplified (step",
	"Automatycznie naprawia 2 pobliskie pojazdy naziemne i roboty": "Automatically repairs 2 nearby ground vehicles and robots",
	"Automatycznie naprawia 2 pobliskie pojazdy naziemne i roboty. Zasięg 190; 16 PW/s na stanowisko; 1 metal za 5 PW. Pobór 20 mocy. Przez 3 s po trafieniu naprawa działa z 25% prędkości; niedobór mocy także ją spowalnia.": "Automatically repairs 2 nearby ground vehicles and robots. Range 190; 16 HP/s per bay; 1 metal per 5 HP. Draws 20 power. For 3 s after being hit, repairs run at 25% speed; a power shortage also slows them.",
	"AUTOSAVE / POTWIERDZENIE": "AUTOSAVE / CONFIRMATION",
	"Awans Kolonii do Twierdzy: centrum o 50% wytrzymalsze, +4 metalu/s": "Upgrade from Colony to Fortress: centre 50% tougher, +4 metal/s",
	"Awans Kolonii do Twierdzy: centrum o 50% wytrzymalsze, +4 metalu/s. Otwiera wybór doktryny frakcji. Wymaga laboratorium.": "Upgrade from Colony to Fortress: centre 50% tougher, +4 metal/s. Unlocks the faction doctrine choice. Requires a Laboratory.",
	"Awans Przyczółka do Kolonii": "Upgrades the Outpost to a Colony",
	"Awans Przyczółka do Kolonii. Odblokowuje fabrykę, laboratorium, hangar i warsztat. Roboty nadal powstają podczas rozbudowy.": "Upgrades the Outpost to a Colony. Unlocks the factory, laboratory, hangar and workshop. Robots can still be built during the upgrade.",
	"Awaryjny desant: załoga straciła 50% pozostałych PW": "Emergency disembark: the crew lost 50% of their remaining HP",
	"Awaryjny desant: załoga straciła 50% pozostałych PW.": "Emergency disembark: the crew lost 50% of their remaining HP.",
