	"Badacz": "Researcher",
	"Badacz z ekipy dr Tessy (akt II, rozdział IV)": "A researcher from Dr Tessa's team (act II, chapter IV)",
	"Badacz z ekipy dr Tessy (akt II, rozdział IV). Nie walczy i ginie po kilku trafieniach. Może jechać transporterem; ewakuuj go na lądowisko przy bazie.": "A researcher from Dr Tessa's team (act II, chapter IV). Does not fight and dies after a few hits. Can ride in a transport; evacuate them to the landing pad by the base.",
	"badacze, ich archiwum i rdzeń danych. Świt ma swoją cenę. Ty zdecydujesz, kto ją zapłaci.": "the researchers, their archive and the data core. Dawn has its price. You will decide who pays it.",
