	"bardzo szybki, widzi na 520, bez broni. Odsłania siedliska i ruchy wroga; strącają go myśliwce, piechota, wieżyczki i obrona przeciwlotnicza. Koszary.": "very fast, sees 520, unarmed. Reveals nests and enemy movements; shot down by Interceptors, infantry, turrets and anti-air defences. Barracks.",
