	"Bastion Dominium": "Dominion Bastion",
	"Bateria przeciwlotnicza": "Flak Battery",
	"Bateria przeciwlotnicza! Omijaj ją kapsułami albo zniszcz uderzeniem z orbity": "Flak Battery! Steer the pods around it or destroy it with a strike from orbit",
	"Bateria przeciwlotnicza! Omijaj ją kapsułami albo zniszcz uderzeniem z orbity.": "Flak Battery! Steer the pods around it or destroy it with a strike from orbit.",
	"Bateria zestrzeliła kapsułę Vok! Stawiajmy je tam, gdzie spada desant": "The battery shot down one of Vok's pods! Let's place them where the landings come down",
	"Bateria zestrzeliła kapsułę Vok! Stawiajmy je tam, gdzie spada desant.": "The battery shot down one of Vok's pods! Let's place them where the landings come down.",
	"Baterie przeciwlotnicze stoją w całej Wypalonej Dolinie": "Flak Batteries stand all across the Scorched Valley",
	"Baterie przeciwlotnicze stoją w całej Wypalonej Dolinie. Każda kapsuła spłonie, zanim dotknie ziemi.": "Flak Batteries stand all across the Scorched Valley. Every pod will burn before it touches ground.",
	"Baterie przeciwlotnicze zestrzeliwują kapsuły": "Flak Batteries shoot down pods",
	"Baza Admiralicji w Dolinie Latarni upada": "The Admiralty base in Lantern Valley falls",
	"Baza Admiralicji w Dolinie Latarni upada. Ale to nie Vok jest największym zmartwieniem: szczeliny przy artefaktach otwierają się na całym pograniczu, a maszyny, które z nich wychodzą, nie odróżniają Kolonii od Dominium. Lira nazywa je Wartownikami.": "The Admiralty base in Lantern Valley falls. But Vok is not the greatest worry: rifts are opening by the artifacts all across the Frontier, and the machines emerging from them cannot tell the Colonies from the Dominion. Lira calls them the Wardens.",
	"BAZA ATAKOWANA —": "BASE UNDER ATTACK —",
	"Baza przetrwała oblężenie": "The base survived the siege",
	"Baza przetrwała oblężenie. Obrona zakończona.": "The base survived the siege. Defence complete.",
	"Baza Varna nie przetrwała, ale jego ludzie ewakuowali się pod osłoną Szczytu": "Varn's base didn't survive, but his people evacuated under cover of the Summit",
	"Baza Varna nie przetrwała, ale jego ludzie ewakuowali się pod osłoną Szczytu.": "Varn's base didn't survive, but his people evacuated under cover of the Summit.",
	"baza Varna przetrwa": "Varn's base survives",
	"Baza wiedzy": "Knowledge Base",
	"BAZA WIEDZY / ARCHIWUM KOLONII": "KNOWLEDGE BASE / COLONY ARCHIVE",
	"Bazaltowe pola i wydłużone przesmyki": "Basalt fields and long narrow passes",
	"Bazaltowe pola i wydłużone przesmyki. Więcej gazu, mniejsze złoża rudy; front biegnie z północy na południe.": "Basalt fields and long narrow passes. More gas, smaller ore deposits; the front runs from north to south.",
	"BESH": "BESH",
	"BETA": "BETA",
	"bez": "without",
	"bez obrażeń przez 3 s": "invulnerable for 3 s",
	"bez obrażeń przez 3 s.": "invulnerable for 3 s.",
	"Bez rozejmu: zniszcz kwaterę Vok": "No truce: destroy Vok's headquarters",
	"Bez rozejmu: zniszcz kwaterę Vok. W rozdziale XIV zaczynasz z 600 metalu więcej z magazynów Admiralicji — sam przeciw Wartownikom.": "No truce: destroy Vok's headquarters. In chapter XIV you start with 600 extra metal from the Admiralty's stores — alone against the Wardens.",
	"bez strat od wybuchu": "no losses from the blast",
	"Bez Varna liczymy na siebie": "Without Varn, we rely on ourselves",
	"Bez Varna liczymy na siebie. Z magazynów floty: 300 metalu na start.": "Without Varn, we rely on ourselves. From the fleet's stores: 300 metal at the start.",
	"Bez wrogich desantów": "No enemy landings",
	"Bez wrogiej bazy: z krawędzi mapy nadchodzą coraz większe i silniejsze fale (czołgi od 3": "No enemy base: ever larger and stronger waves come from the edges of the map (tanks from wave 3, Heavy Walkers from wave 6, aircraft from wave 8, artillery from wave 10)",
	"Bez wrogiej bazy: z krawędzi mapy nadchodzą coraz większe i silniejsze fale (czołgi od 3., ciężkie maszyny od 6., lotnictwo od 8., artyleria od 10. fali). Gra kończy się utratą centrum; liczy się czas i liczba fal, a najlepszy wynik na każdej mapie i poziomie jest zapamiętywany. Liczba graczy i rodzaj przeciwnika nie mają znaczenia.": "No enemy base: ever larger and stronger waves come from the edges of the map (tanks from wave 3, Heavy Walkers from wave 6, aircraft from wave 8, artillery from wave 10). The game ends when you lose your centre; time and waves survived count, and the best result on every map and difficulty is recorded. The number of players and the type of opponent do not matter.",
	"Bez zapisanych decyzji": "No decisions recorded",
	"Bez zmian": "No change",
	"Bez zmian.": "No change.",
	"Bezczynne": "Idle",
	"Bezczynne roboty": "Idle robots",
