	"Bezczynne roboty:": "Idle robots:",
	"bezczynnych robotów": "idle robots",
	"bezczynnych robotów. Przydziel im zadania.": "idle robots. Assign them tasks.",
	"Bezpośrednio — 1 na 1 przez kody": "Direct — 1v1 via codes",
	"Bezzałogowy zwiad z powietrza: bardzo szybki, widzi na 520, bez broni": "Unmanned aerial reconnaissance: very fast, sees 520, unarmed",
	"Bezzałogowy zwiad z powietrza: bardzo szybki, widzi na 520, bez broni. Odsłania siedliska i ruchy wroga; strącają go myśliwce, piechota, wieżyczki i obrona przeciwlotnicza. Koszary.": "Unmanned aerial reconnaissance: very fast, sees 520, unarmed. Reveals nests and enemy movements; shot down by Interceptors, infantry, turrets and anti-air defences. Barracks.",
	"Biały Przesmyk": "White Pass",
	"Biały Przesmyk: lodowa przełęcz i garnizon Dominium": "White Pass: an icy pass and a Dominion garrison",
	"Biały Przesmyk: lodowa przełęcz i garnizon Dominium.": "White Pass: an icy pass and a Dominion garrison.",
	"Bilans": "Balance",
	"Bilans mocy": "Power balance",
	"Bitwa": "Battle",
	"Bitwa jeden na jeden z drugim graczem, bez serwera: przeglądarki łączą się bezpośrednio (WebRTC)": "A one-on-one battle with another player, no server needed: the browsers connect directly (WebRTC)",
	"Bitwa jeden na jeden z drugim graczem, bez serwera: przeglądarki łączą się bezpośrednio (WebRTC). Jeden gracz tworzy grę i wysyła kod zaproszenia, drugi odsyła kod odpowiedzi.": "A one-on-one battle with another player, no server needed: the browsers connect directly (WebRTC). One player creates the game and sends an invitation code, the other sends back a reply code.",
	"Bitwa na orbicie gazowego olbrzyma Kharon": "A battle in orbit around the gas giant Kharon",
	"Bitwa na orbicie gazowego olbrzyma Kharon; co jakiś czas przechodzi burza — na zmianę jonowa (słabsza celność, osłony się nie odnawiają), słoneczna (osłony słabną) i deszcz asteroid (uderzenia odłamków, gdy trwa dłużej), a z kryjówki w pasie asteroid najeżdżają piraci — na wszystkie strony. Pas asteroid przecina pole bitwy trzema korytarzami; w środkowym leżą najbogatsze złoża, gaz zbiera się w obłokach mgławicy. Zamiast pojazdów — korwety, fregaty, niszczyciele i krążowniki z regenerującymi się osłonami. W mgławicy statki trudniej trafić, ale osłony się tam nie odnawiają; tuż przy asteroidach statki mają osłonę przed ogniem.": "A battle in orbit around the gas giant Kharon; storms pass through from time to time — in turn ionic (lower accuracy, shields do not recharge), solar (shields weaken) and asteroid showers (debris impacts if it lasts longer), while pirates raid from a hideout in the asteroid belt — attacking every side. The asteroid belt cuts the battlefield with three corridors; the richest deposits lie in the middle one, and gas gathers in nebula clouds. Instead of vehicles — Corvettes, Frigates, Destroyers and Cruisers with regenerating shields. Ships are harder to hit in the nebula, but shields do not recharge there; right next to asteroids, ships have cover from fire.",
	"Bitwa o orbitę — pierwsza faza Inwazji": "Battle for orbit — the first phase of the Invasion",
	"Bitwa sieciowa": "Network battle",
	"Bitwa z graczem": "Battle with",
	"Bitwa z komputerem staje, gdy przełączysz się do innego okna lub karty; wznawiasz ją sam (Spacja lub „Wznów” na planszy). Gra sieciowa nie staje.": "A battle against the computer stops when you switch to another window or tab; you resume it yourself (Space or “Resume” on the board). A network battle does not stop.",
