	"Blokada złamana. Świt ma swoją cenę — a coś w głębi pogranicza właśnie się obudziło.": "The blockade is broken. Dawn has its price — and something deep in the Frontier has just awoken.",
	"blokadę zasila coś daleko w pograniczu — coś, co wysysa energię całej planety.": "the blockade is fed by something deep in the Frontier — something draining a whole planet's energy.",
