	"Ctrl+S": "Ctrl+S",
	"Ctrl+S — zapis lokalny": "Ctrl+S — local save",
	"Ctrl+S — zapis lokalny; automatyczny zapis co 10 sekund aktywnej bitwy. Pięć ręcznych slotów w menu pauzy oraz oddzielny autosave. Spacja zatrzymuje symulację i pozwala wydawać rozkazy, Esc otwiera menu pauzy.": "Ctrl+S — local save; autosave every 10 seconds of active battle. Five manual slots in the pause menu plus a separate autosave. Space pauses the simulation and lets you give orders; Esc opens the pause menu.",
	"CYTADELA PADA": "THE CITADEL FALLS",
