	"Cytadela Węzła pada. Zanim się zawali, zdążymy zabezpieczyć tylko jedno: magazyny broni albo celę z oficerami Dominium. Decyzja zmienia rozdziały IV–VI.": "The Nexus Citadel is falling. Before it collapses we can secure only one thing: the weapon stores or the cell holding Dominion officers. The decision changes chapters IV–VI.",
