	"Czterech graczy, ubogie złoża i szybki wyścig o przekaźniki (60 pkt na przekaźnik) z trudnym przeciwnikiem.": "Four players, scarce deposits and a fast race for the relays (60 pts per relay) against a hard opponent.",
