	"Daleki ostrzał obszarowy": "Long-range area fire",
	"Daleki ostrzał obszarowy. Potrzebuje eskorty i dystansu do przeciwnika.": "Long-range area fire. Needs an escort and distance from the enemy.",
	"Daleki zasięg przeciw pojazdom · fabryka": "Long range against vehicles · factory",
	"daleki zasięg, +60% obrażeń pojazdom, słaby przeciw piechocie.": "long range, +60% damage to vehicles, weak against infantry.",
	"Dane Liry prowadzą do zapomnianego archiwum na Vesperze": "Lira's data leads to a forgotten archive on Vesper",
	"Dane Liry prowadzą do zapomnianego archiwum na Vesperze. Dominium odcięło szlak zaopatrzenia między lodowymi jeziorami. Zabezpiecz dwa przekaźniki i dwa magazyny, a następnie odbierz port. W archiwum czeka klucz do sieci oraz prawda: blackout miał zmusić Kolonie do kapitulacji.": "Lira's data leads to a forgotten archive on Vesper. The Dominion has cut the supply route between the frozen lakes. Secure two relays and two depots, then retake the port. In the archive await the key to the network and the truth: the blackout was meant to force the Colonies to surrender.",
	"Dane sondy opuszczają wykop": "The probe data is leaving the dig site",
	"Dane sondy opuszczają wykop. Wszystkie jednostki: przechwycić transporter!": "The probe data is leaving the dig site. All units: intercept the transport!",
	"Dane z Eos prowadzą na Vesper": "The Eos data leads to Vesper",
	"Dane z Eos prowadzą na Vesper. Pod lodem leży archiwum dawnej sieci latarni.": "The Eos data leads to Vesper. Beneath the ice lies an archive of the old beacon network.",
