	"dev-tab-": "dev-tab-",
	"Dla map planet (na mapie kosmicznej gra się zwykły podbój)": "For planet maps (on the space map a normal Conquest is played)",
	"Dla map planet (na mapie kosmicznej gra się zwykły podbój). Operacja w dwóch fazach. Najpierw bitwa na orbicie nad planetą (do 8 minut — wygrywa ten, kto zniszczy stację wroga albo ma wtedy silniejszą flotę i stacje), potem bitwa na planecie. Kto panuje na orbicie, ma kapsuły desantowe (z ocalałej floty), uderzenie z orbity bez stacji i skan orbitalny; baterie przeciwlotnicze zestrzeliwują kapsuły.": "For planet maps (on the space map a normal Conquest is played). An operation in two phases. First a battle in orbit above the planet (up to 8 minutes — won by whoever destroys the enemy station or has the stronger fleet and stations by then), then a battle on the planet. Whoever controls the orbit gets drop pods (from the surviving fleet), an orbital strike without a station and an orbital scan; Flak Batteries shoot the pods down.",
	"DŁUG ZA HEFAJSTOS · SOJUSZ · CEL: RÓJ": "HEPHAESTUS DEBT · ALLIANCE · TARGET: SWARM",
	"Dług za Hefajstos spłacam osobiście: dwa niszczyciele czołgów dołączają do waszej kolumny": "I'm repaying the Hephaestus debt personally: two Tank Destroyers are joining your column",
	"Dług za Hefajstos spłacam osobiście: dwa niszczyciele czołgów dołączają do waszej kolumny.": "I'm repaying the Hephaestus debt personally: two Tank Destroyers are joining your column.",
	"Dług za Popielny Szlak spłacam na Nivalis: moi ludzie i bateria przeciwlotnicza są z wami": "I'm repaying the Ash Trail debt on Nivalis: my people and a Flak Battery are with you",
	"Dług za Popielny Szlak spłacam na Nivalis: moi ludzie i bateria przeciwlotnicza są z wami.": "I'm repaying the Ash Trail debt on Nivalis: my people and a Flak Battery are with you.",
