	"do 420 obrażeń w promieniu 110 — tylko wrogom. Odnowienie 100 s.": "up to 420 damage within 110 — enemies only. Cooldown 100 s.",
	"do 50% za budowlę, 100% za fundament. Centrum nie można rozebrać.": "up to 50% for a structure, 100% for a foundation. The Centre cannot be dismantled.",
	"do 900 energii, ładowanie do 15/s. Przy niedoborze oddaje do 30 mocy (30 s przy pełnym obciążeniu). Powstaje pusty; nie zastępuje reaktora.": "up to 900 energy, charging up to 15/s. During a shortage it supplies up to 30 power (30 s at full load). Built empty; does not replace a reactor.",
