	"do naszych robotów!": "for our robots!",
	"DO WOLNYCH KOLONII POGRANICZA:": "TO THE FREE COLONIES OF THE FRONTIER:",
	"Doba": "Day length",
	"Doba trwa 6 minut": "A day lasts 6 minutes",
	"Doba trwa 6 minut. Nocą oddziały i budynki włączają światła. Burze: od 90 s, co 210 s, przez 55 s. Maksymalnie −35% szybkości ruchu i −30% celności. Laboratorium: monitoring prognozuje pogodę i ostrzega 30 s wcześniej; celowanie adaptacyjne oraz napędy terenowe redukują odpowiednią karę o 75%. Ptaki i ryby są dekoracyjną fauną.": "A day lasts 6 minutes. At night units and buildings switch their lights on. Storms: from 90 s, every 210 s, for 55 s. Up to −35% movement speed and −30% accuracy. Laboratory: Weather Monitoring forecasts the weather and warns 30 s ahead; Adaptive Targeting and All-terrain Drives reduce the matching penalty by 75%. Birds and fish are decorative fauna.",
