	"Dolina Latarni": "Lantern Valley",
	"Dolina Latarni po desancie Admiralicji": "Lantern Valley after the Admiralty landing",
	"Dolina Latarni po desancie Admiralicji. Na miejscu latarni leży rozbity krążownik, przez którego pęknięte sekcje prowadzą przejścia, a kotlinę zasypały szczątki zestrzelonych kapsuł. Oazy przetrwały, ruiny osady — nie wszystkie.": "Lantern Valley after the Admiralty landing. A wrecked cruiser lies where the beacon stood, with passages through its broken sections, and the basin is strewn with the debris of downed pods. The oases survived; the settlement ruins — not all of them.",
