	"DOMINIUM · VARN": "DOMINION · VARN",
	"Dominium buduje więcej wieżyczek, rzadko zajmuje przekaźniki, atakuje wolno, ale dużymi grupami ciężkich maszyn i bastionów": "The Dominion builds more turrets and rarely takes relays",
	"Dominium buduje więcej wieżyczek, rzadko zajmuje przekaźniki, atakuje wolno, ale dużymi grupami ciężkich maszyn i bastionów.": "The Dominion builds more turrets and rarely takes relays; it attacks slowly, but with large groups of Heavy Walkers and Bastions.",
	"Dominium kopało w ruinach dawnej sondy — a w jej archiwum zapisano, skąd naprawdę płynie energia blokady": "The Dominion was digging in the ruins of an old probe — and its archive recorded where the blockade's power truly comes from",
	"Dominium kopało w ruinach dawnej sondy — a w jej archiwum zapisano, skąd naprawdę płynie energia blokady.": "The Dominion was digging in the ruins of an old probe — and its archive recorded where the blockade's power truly comes from.",
	"Dominium patrzyło na pogranicze jak na zbuntowaną prowincję": "The Dominion saw the Frontier as a rebel province",
	"Dominium patrzyło na pogranicze jak na zbuntowaną prowincję. Czekało tylko na pretekst.": "The Dominion saw the Frontier as a rebel province. It was only waiting for a pretext.",
