	"Doprowadź co najmniej 2 z 3 konwojowców do latarni Kestrel przez postoje ALFA i BETA. Dodatkowo: zachowaj wszystkie pojazdy konwoju.": "Bring at least 2 of 3 convoy trucks to the Kestrel beacon via stops ALPHA and BETA. Bonus: keep every convoy vehicle intact.",
