	"Dr Tessa zbadała odłamek artefaktu z Hefajstosa. Wzór w krysztale nie był maszyną. Był żywy — i rósł.": "Dr Tessa studied an artifact shard from Hephaestus. The pattern in the crystal was no machine. It was alive — and growing.",
	"Drapieżnik": "Raptor",
	"Drapieżniki bronią siedlisk i zagrażają obu frakcjom": "Predators guard their lairs and threaten both factions",
	"Drapieżniki bronią siedlisk i zagrażają obu frakcjom.": "Predators guard their lairs and threaten both factions.",
	"drawImage (9)": "drawImage (9)",
	"Droga tam wiedzie przez rdzenie energetyczne ukryte za lodową przełęczą Vesperu": "The way there runs through energy cores hidden beyond Vesper's frozen pass",
	"Droga tam wiedzie przez rdzenie energetyczne ukryte za lodową przełęczą Vesperu. Ktoś będzie musiał je przewieźć.": "The way there runs through energy cores hidden beyond Vesper's frozen pass. Someone will have to haul them out.",
