	"Duża": "Large",
	"Dwa bastiony Admiralicji w przeciwległych narożnikach, każdy za murem z dwiema bramami i wieżą na rogu": "Two Admiralty bastions in opposite corners, each behind a wall with two gates and a tower on the corner",
	"Dwa bastiony Admiralicji w przeciwległych narożnikach, każdy za murem z dwiema bramami i wieżą na rogu. Między nimi biegnie Popielny Szlak: stare wieże przetwarzania, ściany narośli i złoża, o które trzeba walczyć w otwartym polu. Bez przełamania bram szturm na centrum nie ma sensu.": "Two Admiralty bastions in opposite corners, each behind a wall with two gates and a tower on the corner. Between them runs the Ash Trail: old processing towers, walls of growths and deposits that must be fought for in the open. Without breaking the gates, storming the centre is pointless.",
	"Dwa magazyny i dwa przekaźniki — potem odbierzemy port": "Two depots and two relays — then we take back the port",
	"Dwa magazyny i dwa przekaźniki — potem odbierzemy port. Uważaj, tamtejszy dowódca zna swój fach.": "Two depots and two relays — then we take back the port. Careful, the commander there knows his trade.",
	"dwa niszczyciele czołgów dołączają do waszej kolumny.": "two Tank Destroyers join your column.",
	"dwa przekaźniki. Potem baza Admiralicji.": "two relays. Then the Admiralty base.",
	"Dwaj strażnicy obok siebie scalają się w konstrukt": "Two Wardens side by side merge into a Construct",
	"Dwaj strażnicy obok siebie scalają się w konstrukt.": "Two Wardens side by side merge into a Construct.",
	"Dwaj strażnicy scalili się w konstrukt": "Two Wardens have merged into a Construct",
	"Dwaj strażnicy scalili się w konstrukt.": "Two Wardens have merged into a Construct.",
	"Dwie minuty do rozstrzygnięcia orbity": "Two minutes until the orbit is decided",
	"Dwie minuty do rozstrzygnięcia orbity.": "Two minutes until the orbit is decided.",
	"dwie szerokie cieśniny wiją się wokół wyspy środkowej z najbogatszymi złożami i rozdzielają wybrzeża, na których stoją bazy. Na wyspę i między wybrzeżami prowadzą tylko mielizny — każdą łatwo zablokować, a kto trzyma brody, ten trzyma środek. Co cztery minuty przychodzi przypływ i na minutę zalewa mielizny. Na plażach gnieżdżą się pajęczaki, sztormy przychodzą z deszczem i piorunami.": "two wide straits wind around a central island with the richest deposits and divide the coasts where the bases stand. Only shoals lead to the island and between the coasts — each is easy to block, and whoever holds the fords holds the centre. Every four minutes the tide comes in and floods the shoals for a minute. Spiders nest on the beaches, and gales bring rain and lightning.",
	"Dystans z rozdziału VIII: Varn nie miesza się do wojny z Admiralicją": "The distance from chapter VIII: Varn stays out of the war with the Admiralty",
	"Dystans z rozdziału VIII: Varn nie miesza się do wojny z Admiralicją. Kolonie liczą na własne zapasy — 250 metalu więcej w rozdziale X i 300 w XI.": "The distance from chapter VIII: Varn stays out of the war with the Admiralty. The Colonies rely on their own supplies — 250 extra metal in chapter X and 300 in XI.",
