	"Dzięki lodowemu szlakowi Kolonie docierają do kuźni Dominium": "Thanks to the ice trail, the Colonies reach the Dominion's forge",
	"Dzięki lodowemu szlakowi Kolonie docierają do kuźni Dominium. Wystaw ciężką maszynę oraz artylerię, odetnij łączność i przełam ostatni bastion.": "Thanks to the ice trail, the Colonies reach the Dominion's forge. Field a Heavy Walker and Artillery, cut communications and break the last bastion.",
