	"Grenadierzy Kolonii: granaty ranią także piechotę stojącą obok celu.": "Colony Grenadiers: grenades also hurt infantry standing next to the target.",
	"Grenadierzy Wolnych Kolonii (koszary): zasięg 170, granaty zadają 40% obrażeń także jednostkom naziemnym w promieniu 45 m od celu": "Free Colonies Grenadiers (Barracks): range 170, grenades also deal 40% damage to ground units within 45 m of the target",
	"Grenadierzy Wolnych Kolonii (koszary): zasięg 170, granaty zadają 40% obrażeń także jednostkom naziemnym w promieniu 45 m od celu.": "Free Colonies Grenadiers (Barracks): range 170, grenades also deal 40% damage to ground units within 45 m of the target.",
	"Gromadzi nadwyżkę mocy: do 900 energii, ładowanie do 15/s": "Stores surplus power: up to 900 energy, charging up to 15/s",
	"Gromadzi nadwyżkę mocy: do 900 energii, ładowanie do 15/s. Przy niedoborze oddaje do 30 mocy (30 s przy pełnym obciążeniu). Powstaje pusty; nie zastępuje reaktora.": "Stores surplus power: up to 900 energy, charging up to 15/s. During a shortage it supplies up to 30 power (30 s at full load). Built empty; does not replace a reactor.",
