	"Gry widoczne dla wszystkich na serwerze": "Games visible to everyone on the server",
	"Gry widoczne dla wszystkich na serwerze; drużyny 2 na 2, komputer na wolnym miejscu, powrót do bitwy po zerwaniu połączenia. Adres pusty — serwer, z którego wczytano grę": "Games visible to everyone on the server; 2 v 2 teams, the computer takes a free slot, rejoin the battle after a disconnect. Empty address — the server the game was loaded from",
