	"Handel": "Trade",
	"Handel (Logistyka → Handel): wymiana metalu, gazu i kryształów po niekorzystnym kursie — tracisz 40% wartości (1 gaz = 3 metalu, 1 kryształ = 2 metalu, np": "Trade (Logistics → Trade): exchange metal, gas and crystals at a poor rate — you lose 40% of the value (1 gas = 3 metal, 1 crystal = 2 metal, e",
	"Handel (Logistyka → Handel): wymiana metalu, gazu i kryształów po niekorzystnym kursie — tracisz 40% wartości (1 gaz = 3 metalu, 1 kryształ = 2 metalu, np. 100 kryształów → 120 metalu). Wymaga ukończonego magazynu polowego lub laboratorium. Dobre na nadmiar, zwłaszcza kryształów.": "Trade (Logistics → Trade): exchange metal, gas and crystals at a poor rate — you lose 40% of the value (1 gas = 3 metal, 1 crystal = 2 metal, e.g. 100 crystals → 120 metal). Requires a completed Field Depot or Laboratory. Good for surpluses, especially crystals.",
	"Handel niedostępny": "Trade unavailable",
	"Handel niedostępny.": "Trade unavailable.",
	"Handel wymaga ukończonego magazynu polowego lub laboratorium": "Trading requires a completed Field Depot or Laboratory",
