	"HEFAJSTOS · POPIÓŁ": "HEPHAESTUS · ASH",
	"Hefajstos runął w ogniu": "Hephaestus fell in flames",
	"Hefajstos runął w ogniu. Blokada pogranicza upadła razem z nim, a ruiny kompleksu płonęły jeszcze przez wiele dni.": "Hephaestus fell in flames. The Frontier blockade fell with it, and the complex's ruins burned for many days.",
	"Hefajstos zgasł": "Hephaestus went dark",
	"Hefajstos zgasł, a blokada pogranicza upadła razem z nim": "Hephaestus went dark, and the Frontier blockade fell with it",
	"Hefajstos zgasł, a blokada pogranicza upadła razem z nim. Na Vulkanie IX zapadła cisza.": "Hephaestus went dark, and the Frontier blockade fell with it. Silence settled over Vulkan IX.",
	"Hefajstos zgasł. Wahadłowce zabrały techników z kompleksu, a blokada pogranicza upadła razem z nim.": "Hephaestus went dark. Shuttles evacuated the complex's technicians, and the Frontier blockade fell with it.",
	"Hefajstos został popiołem na Vulkanie IX": "Hephaestus was left in ashes on Vulkan IX",
	"Hefajstos został popiołem na Vulkanie IX. Cena świtu nie zniknęła z pamięci — ale na popiele nikt już nie budował blokady.": "Hephaestus was left in ashes on Vulkan IX. The price of dawn was never forgotten — but no one built a blockade on those ashes again.",
