	"Ich stacja blokady trzyma całą orbitę. Zniszczmy ją albo wytrzymajmy dziesięć minut — i nie dajmy zatopić lotniskowca.": "Their blockade station holds the entire orbit. Let's destroy it or hold out for ten minutes — and not let them sink the Carrier.",
