	"Import zastąpi wszystkie obecne zapisy bitew i slotów, postęp kampanii, rekordy i ustawienia danymi z pliku": "Importing will replace all current battle and slot saves, campaign progress, records and settings with the data from the file",
	"Import zastąpi wszystkie obecne zapisy bitew i slotów, postęp kampanii, rekordy i ustawienia danymi z pliku. Gra uruchomi się potem ponownie.": "Importing will replace all current battle and slot saves, campaign progress, records and settings with the data from the file. The game will then restart.",
