	"INWAZJA": "INVASION",
	"Inwazja — faza 1: zdobądź orbitę (zniszcz stację wroga albo miej silniejszą flotę po 8 minutach), potem lądowanie": "Invasion — phase 1: take the orbit (destroy the enemy station or have the stronger fleet after 8 minutes), then land",
	"Inwazja — faza 1: zdobądź orbitę (zniszcz stację wroga albo miej silniejszą flotę po 8 minutach), potem lądowanie.": "Invasion — phase 1: take the orbit (destroy the enemy station or have the stronger fleet after 8 minutes), then land.",
	"Inwazja — faza 2: lądowanie": "Invasion — phase 2: landing",
	"Inwazja — faza 2: lądowanie.": "Invasion — phase 2: landing.",
	"INWAZJA · FAZA 1 — ORBITA NAD": "INVASION · PHASE 1 — ORBIT OVER",
	"Inwazja · faza 1 — orbita: zniszcz stację wroga lub miej silniejszą flotę za": "Invasion · phase 1 — orbit: destroy the enemy station or have the stronger fleet in",
	"INWAZJA · FAZA 1 ZAKOŃCZONA /": "INVASION · PHASE 1 COMPLETE /",
	"INWAZJA · FAZA 2 — LĄDOWANIE": "INVASION · PHASE 2 — LANDING",
