	"Inwazja odparta": "The invasion is repelled",
	"INWAZJA ODPARTA": "INVASION REPELLED",
	"Inwazja odparta. Nad Eos wstaje świt — i nikt nie wie, co jeszcze kryje się za horyzontem.": "The invasion is repelled. Dawn rises over Eos — and no one knows what else lies beyond the horizon.",
	"Inwazja wymaga mapy planety — na mapie kosmicznej zagracie Podbój": "Invasion requires a planet map — on a space map you will play Conquest",
	"Inwazja wymaga mapy planety — na mapie kosmicznej zagracie Podbój.": "Invasion requires a planet map — on a space map you will play Conquest.",
	"Inżynierka Lira przetrwała wyłączenie latarni": "Engineer Lira survived the beacon shutdown",
	"Inżynierka Lira przetrwała wyłączenie latarni. Lądujesz na skraju kotliny Eos. Odbuduj zasilanie i laboratorium, przejmij dwie stacje łączności i usuń garnizon, zanim sygnał zamilknie. Z odszyfrowanych danych poznasz drogę do archiwum na Vesperze.": "Engineer Lira survived the beacon shutdown. You land on the edge of the Eos basin. Restore power and the laboratory, capture two comm stations and wipe out the garrison before the signal goes silent. The decrypted data will reveal the way to the archive on Vesper.",
	"Inżynierka Lira zaprojektowała dla nich sieć latarni — przekaźników, które dawały energię, łączność i bezpieczne szlaki": "The engineer Lira designed a network of beacons for them — relays that provided power, communication and safe routes",
	"Inżynierka Lira zaprojektowała dla nich sieć latarni — przekaźników, które dawały energię, łączność i bezpieczne szlaki.": "The engineer Lira designed a network of beacons for them — relays that provided power, communication and safe routes.",
	"Inżynierka sieci": "Network engineer",
	"IPv4": "IPv4",
	"Iskra": "Spark",
	"Iskra Wartowników Otchłani (kuźnia fazowa, 80): szybka, lekka": "Abyss Wardens Spark (Phase Forge, 80): fast, light",
	"Iskra Wartowników Otchłani (kuźnia fazowa, 80): szybka, lekka. Umiejętność Skok (⇧Q, potem LPM): teleport do 260 we wskazany punkt, odnowienie 10 s — na roboty przeciwnika albo z okrążenia.": "Abyss Wardens Spark (Phase Forge, 80): fast, light. Blink ability (⇧Q, then LMB): teleport up to 260 to the chosen point, cooldown 10 s — onto enemy robots or out of an encirclement.",
	"Iskra Wartowników: szybka i lekka": "Warden Spark: fast and light",
	"Iskra Wartowników: szybka i lekka; umiejętność Skok — teleport do 260 w stronę wskazanego punktu, co 10 s.": "Warden Spark: fast and light; Blink ability — teleports up to 260 towards a chosen point, every 10 s.",
	"iskry skaczą we wskazany punkt (LPM), strażnicy wchodzą w fazę.": "Sparks leap to the target point (LMB), Wardens phase out.",
	"IV · Inwazja": "IV · Invasion",
