	"Jakość dźwięku": "Sound quality",
	"Jasne słońce oświetla złote równiny Helionu, porośnięte niskimi drzewami i krzewami": "A bright sun lights the golden plains of Helion, dotted with low trees and shrubs",
	"Jasne słońce oświetla złote równiny Helionu, porośnięte niskimi drzewami i krzewami. Okresowe burze pustynne niosą tumany piasku. Skaliste grzbiety osłaniają środkowy szlak, a oazy i bogate złoża na wschodzie zachęcają do ekspansji. Zabezpiecz przekaźniki i uderz na bazę Dominium.": "A bright sun lights the golden plains of Helion, dotted with low trees and shrubs. Periodic desert storms carry clouds of sand. Rocky ridges shield the central route, while oases and rich deposits in the east invite expansion. Secure the relays and strike the Dominion base.",
