	"Jednostki naziemne +15% szybkości, produkcja o 25% szybsza.": "Ground units +15% speed, production 25% faster.",
	"Jednostki przy kotwicy przeskakują do wskazanej kotwicy (LPM)": "Units near an Anchor jump to the target Anchor (LMB)",
