	"Jednostki w promieniu 220 od własnych budynków i przekaźników otrzymują o 20% mniej obrażeń": "Units within 220 of your own buildings and relays take 20% less damage",
	"Jednostki w promieniu 220 od własnych budynków i przekaźników otrzymują o 20% mniej obrażeń; wieże obronne +25% obrażeń.": "Units within 220 of your own buildings and relays take 20% less damage; defence towers +25% damage.",
	"Jedź": "Drive",
	"jego garnizon na wschodnim grzbiecie otoczyli Wartownicy. Ten sam uplink może jednak uderzyć w stocznię Admiralicji, zanim Vok zwoduje nowe okręty. Decyzja zmienia rozdział XIII.": "his garrison on the eastern ridge is surrounded by the Wardens. Yet the same uplink can strike the Admiralty shipyard before Vok launches new ships. The decision changes chapter XIII.",
	"jego okrętów przy Bramie nie będzie.": "his ships will not be at the Gate.",
	"Jej flota zamknęła orbitę Eos, zajęła doki stoczni i odcięła Kolonie od pogranicza": "Her fleet sealed Eos orbit, seized the shipyard docks and cut the Colonies off from the Frontier",
	"Jej flota zamknęła orbitę Eos, zajęła doki stoczni i odcięła Kolonie od pogranicza.": "Her fleet sealed Eos orbit, seized the shipyard docks and cut the Colonies off from the Frontier.",
	"Jej sygnał przebił blokadę": "Her signal broke through the blockade",
	"Jej sygnał przebił blokadę. W szyfrze ukryła coś więcej: drogę do archiwum na Vesperze, gdzie czeka klucz do sieci.": "Her signal broke through the blockade. In the cipher she hid something more: the way to the archive on Vesper, where the key to the network waits.",
	"Jeleń": "Deer",
	"JENTH": "JENTH",
	"Jeńcy z Nadiru wskazali słabe punkty budowli Dominium": "The prisoners from Nadir pointed out the weak points of Dominion structures",
	"Jeńcy z Nadiru wskazali słabe punkty budowli Dominium. I obiecali, że ich ludzie nie strzelą do ewakuacji.": "The prisoners from Nadir pointed out the weak points of Dominion structures. And they promised their people won't fire on the evacuation.",
