	"Każda kapsuła, która spadnie na Eos, spłonie w powietrzu": "Every pod that falls on Eos will burn up in the air",
	"Każda kapsuła, która spadnie na Eos, spłonie w powietrzu. Baterie już stoją.": "Every pod that falls on Eos will burn up in the air. The batteries are already in place.",
	"Każdy kontrolowany przekaźnik daje 1 punkt na sekundę": "Each controlled relay gives 1 point per second",
	"Każdy kontrolowany przekaźnik daje 1 punkt na sekundę. Pierwsza strona, która zbierze pulę (90 pkt na przekaźnik na mapie), wygrywa. Desanty przeciwnika celują w przekaźniki. Zniszczenie wszystkich centrów nadal daje zwycięstwo.": "Each controlled relay gives 1 point per second. The first side to reach the target (90 pts per relay on the map) wins. Enemy landings target the relays. Destroying all centres still wins the game.",
	"Każdy na każdego": "Free-for-all",
	"każdy przekaźnik daje 1 pkt/s. Wygrywa pierwsza strona z pulą": "each relay gives 1 pt/s. The first side to reach a target of",
	"każdy przekaźnik daje 1 pkt/s. Wygrywa pierwsza strona z wymaganą pulą.": "each relay gives 1 pt/s. The first side to reach the target wins.",
	"Każdy punkt zapewnia +5 metalu/s": "Each point provides +5 metal/s",
	"Każdy rozkaz miał swoją cenę": "Every order had its price",
	"Każdy rozkaz miał swoją cenę. Oto decyzje, które ukształtowały pogranicze.": "Every order had its price. These are the decisions that shaped the Frontier.",
