	"Kliknij kategorię, aby zaznaczyć roboty": "Click a category to select its robots",
	"Kliknij kategorię, aby zaznaczyć roboty. Przydział obejmuje też dojazd i transport ładunku.": "Click a category to select its robots. An assignment also covers travel and hauling cargo.",
	"Kliknij klawisz akcji i naciśnij nowy (Esc — anuluj). Zajęty klawisz zamienia się miejscami z poprzednią akcją.": "Click an action's key and press a new one (Esc — cancel). A key already in use swaps places with the previous action.",
	"Kliknij lub naciśnij dowolny klawisz": "Click or press any key",
	"Klimat": "Climate",
	"Klucz jest gotowy": "The key is ready",
	"Klucz jest gotowy. Daj mi czas i ciężki sprzęt, a zapalę latarnie na całym pograniczu.": "The key is ready. Give me time and heavy equipment, and I'll light the beacons across the whole Frontier.",
	"KLUCZ SIECI": "NETWORK KEY",
	"Klucz z Vesperu może przywrócić zasilanie całemu pograniczu": "The key from Vesper can restore power to the whole Frontier",
	"Klucz z Vesperu może przywrócić zasilanie całemu pograniczu. Musisz przejąć węzły sieci przy złożach na Nadirze i rozbić centrum blokady. Lira potrzebuje czasu: przygotuj ciężką maszynę i artylerię. Zwycięstwo zapali latarnie i otworzy szlak dla transportów pomocy.": "The key from Vesper can restore power to the whole Frontier. You must capture the network nodes by the deposits on Nadir and smash the blockade centre. Lira needs time: prepare a Heavy Walker and artillery. Victory will light the beacons and open the route for relief transports.",
	"KM · SKAN": "KM · SCAN",
	"Kmdr Aris Varn": "Cdr. Aris Varn",
	"KMDR ARIS VARN · DOMINIUM": "CDR. ARIS VARN · DOMINION",
	"KMDR VARN: ZDRAJCA": "CDR. VARN: TRAITOR",
