	"Kod gotowy": "Code ready",
	"Kod gotowy. Wyślij go i czekaj na kod odpowiedzi.": "Code ready. Send it and wait for the reply code.",
	"Kod operacji": "Operation code",
	"Kod operacji — do udostępnienia": "Operation code — for sharing",
	"Kody wciąż działają — widzę bazę Dominium na mapie i słyszę ich rozkazy z wyprzedzeniem": "The codes still work — I can see the Dominion base on the map and hear their orders in advance",
	"Kody wciąż działają — widzę bazę Dominium na mapie i słyszę ich rozkazy z wyprzedzeniem.": "The codes still work — I can see the Dominion base on the map and hear their orders in advance.",
	"Kody zostają u Liry": "The codes stay with Lira",
	"Kody zostają u Liry. W rozdziale IX zaczynasz z 400 metalu więcej i własną artylerią.": "The codes stay with Lira. In chapter IX you start with 400 more metal and your own Artillery.",
	"Kolec": "Spike",
