	"Kolejni ochotnicy z Nadiru dołączają do nas": "More volunteers from Nadir are joining us",
	"Kolejni ochotnicy z Nadiru dołączają do nas. Dominium wie, że nadchodzimy.": "More volunteers from Nadir are joining us. The Dominion knows we're coming.",
