	"Konstrukt": "Construct",
	"Konstrukt Wartowników: tytan z połączenia dwóch strażników (nie z produkcji) — 1900 PW, 75 obrażeń": "Warden Construct: a titan formed by merging two Wardens (not produced) — 1900 HP, 75 damage",
	"Konstrukt Wartowników: tytan z połączenia dwóch strażników (nie z produkcji) — 1900 PW, 75 obrażeń; przejmuje średnią wytrzymałość obu strażników.": "Warden Construct: a titan formed by merging two Wardens (not produced) — 1900 HP, 75 damage; inherits the average health of both Wardens.",
