	"kontra": "vs",
	"Kontynuuj": "Continue",
	"Konwojowiec z rdzeniem": "Core Convoy",
	"Konwojowiec z rdzeniem energetycznym (akt II, rozdział V)": "A convoy vehicle carrying an energy core (act II, chapter V)",
	"Konwojowiec z rdzeniem energetycznym (akt II, rozdział V). Jedzie automatycznie między postojami; nie przyjmuje rozkazów. Naprawiają go roboty i warsztat.": "A convoy vehicle carrying an energy core (act II, chapter V). Drives automatically between stops; does not take orders. Repaired by robots and the workshop.",
	"Konwój gotowy": "Convoy ready",
	"Konwój gotowy. Trzy rdzenie, trzy wozy. Ruszamy za 25 sekund i jedziemy sami — waszym zadaniem jest utrzymać postoje i nas łatać.": "Convoy ready. Three cores, three trucks. We roll out in 25 seconds and drive on our own — your job is to hold the stops and patch us up.",
	"Konwój na szlaku": "Convoy on the trail",
	"Konwój na szlaku. Oddział — zatrzymać go.": "Convoy on the trail. Squad — stop it.",
	"Konwój porusza się automatycznie między postojami": "The convoy moves automatically between stops",
	"Konwój porusza się automatycznie między postojami.": "The convoy moves automatically between stops.",
	"Konwój rusza": "The convoy moves out",
	"Konwój rusza za": "Convoy departs in",
	"Konwój rusza. Kierunek: postój ALFA.": "The convoy moves out. Heading: stop ALPHA.",
	"Konwój u celu": "Convoy at destination",
	"Konwój u celu.": "Convoy at destination.",
	"Konwój utracił zbyt wiele rdzeni": "The convoy has lost too many cores",
	"Konwój utracił zbyt wiele rdzeni. Latarnia Kestrel nie zostanie zasilona.": "The convoy has lost too many cores. The Kestrel beacon will not be powered.",
	"Konwój w drodze do:": "Convoy en route to:",
	"kooperacja: druga strona — same komputery": "co-op: the other side is all AI",
	"Kopia zapasowa wszystkiego, co gra trzyma na tym urządzeniu: zapisy bitew i slotów, postęp kampanii, rekordy i ustawienia — do jednego pliku, który wczytasz na innym komputerze lub po ponownej instalacji": "Back up everything the game keeps on this device: battle and slot saves, campaign progress, records and settings — into a single file you can load on another computer or after reinstalling",
	"Kopia zapasowa wszystkiego, co gra trzyma na tym urządzeniu: zapisy bitew i slotów, postęp kampanii, rekordy i ustawienia — do jednego pliku, który wczytasz na innym komputerze lub po ponownej instalacji.": "Back up everything the game keeps on this device: battle and slot saves, campaign progress, records and settings — into a single file you can load on another computer or after reinstalling.",
