	"Koss i technicy z Hefajstosa pracują dla Kolonii": "Koss and the Hephaestus technicians work for the Colonies",
	"Koss i technicy z Hefajstosa pracują dla Kolonii.": "Koss and the Hephaestus technicians work for the Colonies.",
	"Koss, który przeżył wybuch Hefajstosa, został z Koloniami — i nie zapomniał tych, którzy nie zdążyli uciec": "Koss, who survived the Hephaestus explosion, stayed with the Colonies — and has not forgotten those who didn't escape in time",
	"Koss, który przeżył wybuch Hefajstosa, został z Koloniami — i nie zapomniał tych, którzy nie zdążyli uciec.": "Koss, who survived the Hephaestus explosion, stayed with the Colonies — and has not forgotten those who didn't escape in time.",
	"Koszary": "Barracks",
	"Koszt": "Cost",
	"Koszt +15%, wytrzymałość −10%, obrażenia +5%": "Cost +15%, durability −10%, damage +5%",
	"Koszt +15%, wytrzymałość −10%, obrażenia +5%; tarcze na wszystkim, lewitacja (pogoda i teren nie spowalniają). Bez górników — Rezonatory czerpią ze złóż i przekaźników. Unikalne: iskra (skok), pryzmat (narastająca wiązka), łuk (wyładowanie łańcuchowe), strażnik (faza), konstrukt (scalenie dwóch strażników), kotwica (szczeliny i teleporty), rezonator; centrum może przelecieć.": "Cost +15%, durability −10%, damage +5%; shields on everything, levitation (weather and terrain do not slow them). No miners — Resonators draw from deposits and relays. Unique: Spark (blink), Prism (building beam), Arc (chain discharge), Warden (phase), Construct (merge of two Wardens), Anchor (rifts and teleports), Resonator; the centre can fly.",
	"Koszt −15%, wytrzymałość −10%, ruch +8%": "Cost −15%, HP −10%, speed +8%",
	"Koszt −15%, wytrzymałość −10%, ruch +8%. Wszystko się regeneruje (jednostki stale, budynki po 6 s spokoju), wylęganie o 15% szybsze. Unikalne: pełzacz, pluwacz, kolos i monolit rezonansowy.": "Cost −15%, HP −10%, speed +8%. Everything regenerates (units constantly, buildings after 6 s undisturbed), hatching 15% faster. Unique: Crawler, Spitter, Colossus and Resonance Monolith.",
	"KOTLINA EOS": "EOS BASIN",
	"Kotwica": "Anchor",
	"Kotwica Wartowników (180): poszerza strefę budowy o promień 320 i widzi na 380": "Warden Anchor (180): extends the build zone by a radius of 320 and sees 380",
	"Kotwica Wartowników (180): poszerza strefę budowy o promień 320 i widzi na 380. Oddziały z kuźni wychodzą ze szczeliny przy kotwicy najbliższej punktowi zbiórki. Jednostki przy kotwicy przeskakują do innej kotwicy (Do kotwicy, LPM na kotwicę docelową; co 8 s).": "Warden Anchor (180): extends the build zone by a radius of 320 and sees 380. Forge units emerge from a rift at the anchor nearest the rally point. Units at an anchor jump to another anchor (To Anchor, LMB on the target anchor; every 8 s).",
	"Kotwica Wartowników: poszerza strefę budowy (320)": "Warden Anchor: extends the build zone (320)",
	"Kotwica Wartowników: poszerza strefę budowy (320); jednostki z kuźni wychodzą ze szczeliny przy kotwicy najbliższej punktu zbiórki; jednostki przy kotwicy przeskakują do innej.": "Warden Anchor: extends the build zone (320); forge units emerge from a rift at the anchor nearest the rally point; units at an anchor jump to another one.",
