	"KPT": "CAPT",
	"Kpt. Oren Vale": "Capt. Oren Vale",
	"KPT. VALE · KONWÓJ 112 · SZLAK OTWARTY": "CAPT. VALE · CONVOY 112 · ROUTE OPEN",
	"Kpt. Vale znów prowadzi konwoje między wolnymi światami. Każdy sygnał latarni oznacza bezpieczny powrót.": "Capt. Vale leads convoys between the free worlds once more. Every beacon signal means a safe return.",
