	"lodowa przełęcz i garnizon Dominium.": "an icy pass and a Dominion garrison.",
	"Lodowe Archiwum": "Ice Archive",
	"Lodowe grzbiety dzielą szlaki": "Icy ridges divide the routes",
	"Lodowe grzbiety dzielą szlaki. Baza startuje na południowym wschodzie; centralne złoża wymagają ochrony.": "Icy ridges divide the routes. The base starts in the south-east; the central deposits need protecting.",
	"lodowy": "ice",
	"Lodowy olbrzym Glacjalis, przewrócony na bok jak Uran, otacza tarcza lśniących pierścieni z lodu": "The ice giant Glacialis, tipped on its side like Uranus, is circled by a disc of gleaming ice rings",
	"Lodowy olbrzym Glacjalis, przewrócony na bok jak Uran, otacza tarcza lśniących pierścieni z lodu. Pola lodowych brył układają się w skośne pasma i wyznaczają skośne korytarze. Gaz wydobywa się z lodowych komet, kryształy rosną w szczelinach. Burze jonowe i deszcz lodowych odłamków.": "The ice giant Glacialis, tipped on its side like Uranus, is circled by a disc of gleaming ice rings. Fields of ice boulders lie in slanting bands that form diagonal corridors. Gas is drawn from icy comets, crystals grow in the crevices. Ion storms and ice shard showers.",
	"Logistyka": "Logistics",
	"LOGISTYKA KOLONII": "COLONY LOGISTICS",
	"Logistyka mobilna": "Mobile Logistics",
	"Losuj": "Randomise",
	"Lotnictwo": "Aircraft",
	"Lotniskowiec": "Carrier",
	"Lotniskowiec obrywa! Osłoń go albo wycofaj za asteroidy": "The Carrier is taking hits! Cover it or pull it back behind the asteroids",
	"Lotniskowiec obrywa! Osłoń go albo wycofaj za asteroidy.": "The Carrier is taking hits! Cover it or pull it back behind the asteroids.",
	"lotniskowiec przetrwa": "the Carrier survives",
	"Lód": "Ice",
	"LPM / przeciągnij": "LMB / drag",
	"LPM / ramka — zaznaczanie · PPM — rozkaz · A + PPM — atak w marszu": "LMB / box — select · RMB — order · A + RMB — attack-move",
	"LPM / ramka — zaznaczanie · PPM — rozkaz · A + PPM — atak w marszu. Strzałki — kamera, kółko — zoom. Ctrl+1–9 zapisuje grupę, 1–9 ją wybiera. J pokazuje alarm bazy. Shift+S — utrzymanie pozycji. Shift+P i PPM — patrol do punktu i z powrotem; Shift+E i PPM na własnej jednostce lub budynku — eskorta. Z — bezczynne roboty. W trybie 3D (Ustawienia → Renderer) przecinek i kropka albo Alt + przeciąganie środkowym przyciskiem w bok obracają kamerę, PageUp / PageDown albo Alt + przeciąganie w górę i w dół pochylają ją ku horyzontowi (widać niebo), / przywraca widok od południa, a z bliska kamera patrzy niżej, bardziej z boku; latające wyspy, iglice i wielkie grzyby prześwitują, gdy zasłaniają twoje jednostki lub kursor.": "LMB / box — select · RMB — order · A + RMB — attack-move. Arrows — camera, wheel — zoom. Ctrl+1–9 saves a group, 1–9 selects it. J shows the base alert. Shift+S — hold position. Shift+P and RMB — patrol to a point and back; Shift+E and RMB on your own unit or building — escort. Z — idle robots. In 3D mode (Settings → Renderer), comma and full stop or Alt + dragging the middle button sideways rotate the camera, PageUp / PageDown or Alt + dragging up and down tilt it towards the horizon (the sky comes into view), / restores the view from the south, and up close the camera looks lower and more from the side; floating islands, spires and giant mushrooms turn see-through when they hide your units or the cursor.",
	"LPM lub przeciągnij ramkę": "LMB or drag a box",
	"LPM na fioletowym złożu gazu": "LMB on a purple gas deposit",
	"LPM na murze lub wolnym terenie": "LMB on a wall or open ground",
	"LPM przy bazie / przekaźniku": "LMB near the base / a relay",
