	"LUDZIE POGRANICZA": "PEOPLE OF THE FRONTIER",
	"Ludzie Varna wychodzą z okrążenia: od razu dołączają 2 niszczyciele i bastion, a w rozdziale XIII Varn przyprowadzi 2 niszczyciele, bastion i drugą baterię przeciwlotniczą": "Varn's people break out of the encirclement: 2 destroyers and a bastion join at once, and in chapter XIII Varn brings 2 destroyers, a bastion and a second Flak Battery",
	"Ludzie Varna wychodzą z okrążenia: od razu dołączają 2 niszczyciele i bastion, a w rozdziale XIII Varn przyprowadzi 2 niszczyciele, bastion i drugą baterię przeciwlotniczą.": "Varn's people break out of the encirclement: 2 destroyers and a bastion join at once, and in chapter XIII Varn brings 2 destroyers, a bastion and a second Flak Battery.",
