	"Łatwy przeciwnik, bogate złoża, nieliczna fauna i łagodna pogoda na dużej mapie — czas na rozbudowę kolonii.": "An easy opponent, rich deposits, sparse fauna and mild weather on a large map — time to grow your colony.",
