	"Łuk Wartowników (wielka kuźnia, 240): artyleria o zasięgu 380": "Warden Arc (Great Forge, 240): artillery with a range of 380",
	"Łuk Wartowników (wielka kuźnia, 240): artyleria o zasięgu 380; wyładowanie przeskakuje na 2 kolejne wrogie cele w promieniu 110, za każdym razem o połowę słabsze. Groźny dla zbitej piechoty.": "Warden Arc (Great Forge, 240): artillery with a range of 380; the discharge jumps to 2 more enemy targets within 110, half as strong each time. Dangerous to bunched-up infantry.",
