	"Mam kody łączności Dominium": "I have the Dominion's communication codes",
	"Mam kody łączności Dominium. Co z nimi zrobimy?": "I have the Dominion's communication codes. What shall we do with them?",
	"Mamy cię, Miro! Trzymajcie się, idziemy po was": "We've got you, Mira! Hold on, we're coming for you",
	"Mamy cię, Miro! Trzymajcie się, idziemy po was.": "We've got you, Mira! Hold on, we're coming for you.",
	"Mamy lotniskowiec i dziesięć minut": "We have a carrier and ten minutes",
	"Mamy lotniskowiec i dziesięć minut. Przełammy blokadę — z ocalałej floty zrobimy kapsuły na lądowanie.": "We have a carrier and ten minutes. Let's break the blockade — we'll turn the surviving fleet into landing pods.",
