	"MGŁA WOJNY AKTYWNA · ZWIAD ODSŁANIA TEREN": "FOG OF WAR ACTIVE · SCOUTING REVEALS TERRAIN",
	"Mgła wojny skrywa wroga — zwiadowcy i drony widzą najdalej": "Fog of war hides the enemy — scouts and drones see the furthest",
	"Mgła wojny skrywa wroga — zwiadowcy i drony widzą najdalej.": "Fog of war hides the enemy — scouts and drones see the furthest.",
	"MGŁAWICA": "NEBULA",
	"Mgławica Szkarłat": "Crimson Nebula",
	"Miasta pogrążyły się w ciemności": "The cities sank into darkness",
	"Miasta pogrążyły się w ciemności. Bez energii Kolonie miały wytrzymać najwyżej kilka tygodni.": "The cities sank into darkness. Without power, the Colonies could hold out a few weeks at most.",
	"Miasto Prekursorów na Nadirze: siatka zrujnowanych kwartałów przecięta wąskimi ulicami, z szeroką aleją i placem cytadeli w środku": "A Precursor city on Nadir: a grid of ruined blocks cut by narrow streets, with a broad avenue and a citadel square at its heart",
	"Miasto Prekursorów na Nadirze: siatka zrujnowanych kwartałów przecięta wąskimi ulicami, z szeroką aleją i placem cytadeli w środku. Kto trzyma skrzyżowania, ten trzyma złoża. Na dwóch placach dymią stare wieże przetwarzania, a na przedmieściach gnieżdżą się pajęczaki.": "A Precursor city on Nadir: a grid of ruined blocks cut by narrow streets, with a broad avenue and a citadel square at its heart. Whoever holds the crossroads holds the deposits. Old processing towers smoke on two squares, and spiders nest in the outskirts.",
	"Miętowy": "Mint",
	"min": "min",
	"min.": "min.",
	"Minimapa — kliknij, aby przesunąć kamerę": "Minimap — click to move the camera",
	"minut oblężenia": "minutes of siege",
	"minut oblężenia.": "minutes of siege.",
	"Miotacze ognia": "Flamethrowers",
	"Miotacze ognia Dominium (koszary): zasięg 85, szybki ogień": "Dominion Flamethrowers (Barracks): range 85, rapid fire",
	"Miotacze ognia Dominium (koszary): zasięg 85, szybki ogień; ×1,5 przeciw piechocie, ×1,3 przeciw budynkom, ×0,6 przeciw pojazdom; płomień rani też sąsiadów celu.": "Dominion Flamethrowers (Barracks): range 85, rapid fire; ×1.5 against infantry, ×1.3 against buildings, ×0.6 against vehicles; the flame also hurts units next to the target.",
	"Miotacze ognia Dominium: krótki zasięg, ogień obejmuje grupę": "Dominion Flamethrowers: short range, the fire engulfs a group",
	"Miotacze ognia Dominium: krótki zasięg, ogień obejmuje grupę; groźni dla piechoty i budynków.": "Dominion Flamethrowers: short range, the fire engulfs a group; dangerous to infantry and buildings.",
	"Misja": "Mission",
	"Misja nieudana": "Mission failed",
	"Misja nieudana.": "Mission failed.",
	"Mobilna obrona przeciwlotnicza · słaby przeciw celom naziemnym": "Mobile air defence · weak against ground targets",
	"Mobilna obrona przeciwlotnicza: zasięg 330, 28 obrażeń co 0,6 s przeciw lotnictwu": "Mobile anti-air defence: range 330, 28 damage every 0",
	"Mobilna obrona przeciwlotnicza: zasięg 330, 28 obrażeń co 0,6 s przeciw lotnictwu; przeciw celom naziemnym tylko 35%. Towarzyszy armii. Fabryka.": "Mobile anti-air defence: range 330, 28 damage every 0.6 s against aircraft; only 35% against ground targets. Accompanies the army. Factory.",
	"Mobilna OPL · fabryka": "Mobile AA · factory",
	"Mobilność +12%, koszt −10%, wytrzymałość −8%": "Mobility +12%, cost −10%, durability −8%",
	"Mobilność +12%, koszt −10%, wytrzymałość −8%, budowa o 20% szybsza, regeneracja poza walką": "Mobility +12%, cost −10%, durability −8%, 20% faster construction, regeneration out of combat",
	"Mobilność +12%, koszt −10%, wytrzymałość −8%, budowa o 20% szybsza, regeneracja poza walką. Unikalne: zwiadowca, grenadierzy, łazik serwisowy i placówka polowa.": "Mobility +12%, cost −10%, durability −8%, 20% faster construction, regeneration out of combat. Unique: scout, grenadiers, service rover and field outpost.",
	"Mobilność +12%, koszt −10%, wytrzymałość −8%. Unikalny zwiadowca; regeneracja poza walką.": "Mobility +12%, cost −10%, durability −8%. Unique scout; regeneration out of combat.",
	"Mobilny pancerz i siła ognia": "Mobile armour and firepower",
	"Mobilny pancerz i siła ognia. Wymaga fabryki.": "Mobile armour and firepower. Requires a factory.",
