	"Najpierw jednak Eos. Ocalała flota Kolonii zbiera się, by przełamać blokadę.": "But first, Eos. The surviving Colony fleet is gathering to break the blockade.",
	"Najpierw jednak Khepri IV: badacze, ich archiwum i rdzeń danych": "But first, Khepri IV: the researchers, their archive and the data core",
	"Najpierw jednak Khepri IV: badacze, ich archiwum i rdzeń danych. Świt ma swoją cenę. Ty zdecydujesz, kto ją zapłaci.": "But first, Khepri IV: the researchers, their archive and the data core. Dawn has its price. You will decide who pays it.",
