	"Obrona wyłącznie przeciwlotnicza: zasięg 360, 40 obrażeń co 0,8 s": "Anti-air defence only: range 360, 40 damage every 0",
	"Obrona wyłącznie przeciwlotnicza: zasięg 360, 40 obrażeń co 0,8 s. Zużywa 15 mocy. Wymaga Kolonii i eskorty przeciw wojskom naziemnym.": "Anti-air defence only: range 360, 40 damage every 0.8 s. Uses 15 power. Requires Colony and an escort against ground forces.",
