	"Obsługa gazu": "Gas operation",
	"Obsługiwane i pobliskie złoża": "Worked and nearby deposits",
	"OCAL JEŃCÓW": "SAVE THE PRISONERS",
	"Ocalała flota = kapsuły w rozdziale XI": "Surviving fleet = pods in chapter XI",
	"Oceaniczny świat Thalassy: dwie szerokie cieśniny wiją się wokół wyspy środkowej z najbogatszymi złożami i rozdzielają wybrzeża, na których stoją bazy": "The ocean world of Thalassa: two wide straits wind around a central island with the richest deposits and divide the coasts where the bases stand",
	"Oceaniczny świat Thalassy: dwie szerokie cieśniny wiją się wokół wyspy środkowej z najbogatszymi złożami i rozdzielają wybrzeża, na których stoją bazy. Na wyspę i między wybrzeżami prowadzą tylko mielizny — każdą łatwo zablokować, a kto trzyma brody, ten trzyma środek. Co cztery minuty przychodzi przypływ i na minutę zalewa mielizny. Na plażach gnieżdżą się pajęczaki, sztormy przychodzą z deszczem i piorunami.": "The ocean world of Thalassa: two wide straits wind around a central island with the richest deposits and divide the coasts where the bases stand. Only shoals lead to the island and between the coasts — each is easy to block, and whoever holds the fords holds the centre. Every four minutes the tide comes in and floods the shoals for a minute. Spiders nest on the beaches, and gales bring rain and lightning.",
	"Ochotnicy dołączą do Ciebie: 2 piechurów i rakietowiec na start rozdziałów II i III": "Volunteers will join you: 2 Infantry and a Rocketeer at the start of chapters II and III",
	"Ochotnicy dołączą do Ciebie: 2 piechurów i rakietowiec na start rozdziałów II i III. Dominium usłyszy apel — jego dowódca zacznie z 150 metalu więcej.": "Volunteers will join you: 2 Infantry and a Rocketeer at the start of chapters II and III. The Dominion will hear the appeal — its commander will start with 150 more metal.",
	"OCZEKIWANIE NA ROZKAZY": "AWAITING ORDERS",
	"od gospodarza": "from the host",
	"od gospodarza.": "from the host.",
	"od południa": "from the south",
	"od razu dołączają 2 niszczyciele i bastion, a w rozdziale XIII Varn przyprowadzi 2 niszczyciele, bastion i drugą baterię przeciwlotniczą.": "2 Tank Destroyers and a Bastion join at once, and in chapter XIII Varn brings 2 Tank Destroyers, a Bastion and a second Flak Battery.",
	"od Twojego centrum": "from your centre",
	"Od wyłączenia Hefajstosa artefakty obcych w całym pograniczu świecą jednym rytmem": "Since Hephaestus was shut down, alien artifacts across the Frontier have been glowing to a single rhythm",
	"Od wyłączenia Hefajstosa artefakty obcych w całym pograniczu świecą jednym rytmem. Na Lumerii V sygnał jest najsilniejszy — i właśnie tam z kryształowych grot wyszło coś żywego. Zdobądź artefakt, zanim zabierze go Rój, i dowieź go do bazy, by Lira mogła go zbadać.": "Since Hephaestus was shut down, alien artifacts across the Frontier have been glowing to a single rhythm. On Lumeria V the signal is strongest — and it is there that something alive has emerged from the crystal caves. Seize the artifact before the Swarm takes it, and bring it to base so Lira can study it.",
	"Od wyłączenia Hefajstosa artefakty w całym pograniczu pulsują jednym rytmem": "Since Hephaestus went down, artifacts across the Frontier have been pulsing to a single rhythm",
	"Od wyłączenia Hefajstosa artefakty w całym pograniczu pulsują jednym rytmem.": "Since Hephaestus went down, artifacts across the Frontier have been pulsing to a single rhythm.",
	"Odbicia w wodzie 3D (brzegi, budynki, niebo)": "3D water reflections (shores, buildings, sky)",
