	"ODBUDUJ STACJĘ": "REBUILD THE STATION",
	"Odbuduj zasilanie": "Restore the power",
	"Odbuduj zasilanie. Przejmij łączność. Zapal latarnię. Odzyskany Świt zaczyna się od Twojego rozkazu.": "Restore the power. Seize the communications. Light the beacon. Reclaimed Dawn begins with your order.",
	"odcinek · Alt + przeciągnij: okrąg": "segment · Alt + drag: circle",
	"odcinek pod dowolnym kątem. Alt + przeciągnięcie: okrąg. Blokuje ruch obu stron.": "a segment at any angle. Alt + drag: a circle. Blocks movement for both sides.",
