	"Odjazd z": "Departing",
	"Odkąd Hefajstos nie istnieje, Rój stracił źródło energii — jego gniazda są słabsze": "With Hephaestus gone, the Swarm has lost its power source — its nests are weaker",
	"Odkąd Hefajstos nie istnieje, Rój stracił źródło energii — jego gniazda są słabsze. Rdzenie z ruin dały nam 250 metalu.": "With Hephaestus gone, the Swarm has lost its power source — its nests are weaker. Cores from the ruins gave us 250 metal.",
