	"Odłamki zaczną uderzać w statki i stacje — chronią osłony przeciwmeteorytowe.": "Debris will start striking ships and stations — Meteor Shields protect them.",
	"ODŁĄCZ I EWAKUUJ PERSONEL": "DISCONNECT AND EVACUATE THE STAFF",
	"ODŁĄCZANIE": "DISCONNECTING",
	"ODŁĄCZENIE": "DISCONNECTION",
	"Odłączyliśmy kompleks": "We've disconnected the complex",
	"Odłączyliśmy kompleks. Sześcioro techników wychodzi — odprowadźcie nas na lądowisko przy waszej bazie. Pajęczaki wpadły w szał!": "We've disconnected the complex. Six technicians are coming out — escort us to the landing pad by your base. The spiders have gone berserk!",
	"Odnajdź obóz badaczy na północnym wschodzie": "Find the research camp in the north-east",
	"Odnajdź obóz badaczy, odczytaj archiwum, dostarcz rdzeń danych transporterem na lądowisko i ewakuuj co najmniej 2 badaczy": "Find the researchers' camp, read the archive, deliver the data core by transport to the landing zone and evacuate at least 2 researchers",
	"Odnajdź obóz badaczy, odczytaj archiwum, dostarcz rdzeń danych transporterem na lądowisko i ewakuuj co najmniej 2 badaczy. Dodatkowo: ewakuuj wszystkich czterech.": "Find the researchers' camp, read the archive, deliver the data core by transport to the landing zone and evacuate at least 2 researchers. Bonus: evacuate all four.",
