	"odzyskany": "reclaimed",
	"Odzyskany Świt": "Reclaimed Dawn",
	"ODZYSKANY ŚWIT": "DAWN RECLAIMED",
	"Odzyskany Świt. Ekspedycja ląduje przy opuszczonej stacji. Przywróć łączność, uruchom reaktor i laboratorium, a następnie usuń garnizon Dominium.": "Reclaimed Dawn. The expedition lands by an abandoned station. Restore communications, bring a Reactor and Laboratory online, then remove the Dominion garrison.",
	"odzyskany.": "reclaimed.",
	"Oficerowie zdradzą słabe punkty: wieże i budynki Dominium w rozdziałach IV–VI mają o 10% mniej wytrzymałości (najwięcej znaczy to w kompleksie Hefajstos), a posiłki z orbity mogą nadejść dwa razy": "The officers will reveal weak points: Dominion towers and buildings in chapters IV–VI have 10% less HP (this matters most in the Hephaestus Complex), and reinforcements from orbit can arrive twice",
	"Oficerowie zdradzą słabe punkty: wieże i budynki Dominium w rozdziałach IV–VI mają o 10% mniej wytrzymałości (najwięcej znaczy to w kompleksie Hefajstos), a posiłki z orbity mogą nadejść dwa razy.": "The officers will reveal weak points: Dominion towers and buildings in chapters IV–VI have 10% less HP (this matters most in the Hephaestus Complex), and reinforcements from orbit can arrive twice.",
	"Ognisty świat kompleksu Hefajstos, otoczony pasem asteroid": "Fiery world of the Hephaestus Complex, ringed by an asteroid belt",
