	"OKRĘT DESANTOWY „ŚWIT” · DOWÓDCA: TY": "LANDING SHIP “DAWN” · COMMANDER: YOU",
	"Okręt piracki": "Pirate Ship",
	"Okręty Varna (fregata i korweta) lecą z Tobą —": "Varn's ships (a Frigate and a Corvette) fly with you —",
	"Okręty Vok i Kolonii wracają z Erebusa razem": "Vok's ships and the Colonies' fleet return from Erebus together",
	"Okręty Vok i Kolonii wracają z Erebusa razem — Admiralicja podpisuje rozejm, którego kiedyś nie uznała": "Vok's ships and the Colonies return from Erebus together — the Admiralty signs a truce it once refused to recognise",
	"Okręty Vok i Kolonii wracają z Erebusa razem — Admiralicja podpisuje rozejm, którego kiedyś nie uznała.": "Vok's ships and the Colonies return from Erebus together — the Admiralty signs a truce it once refused to recognise.",
	"Okręty Vok i Kolonii wracają z Erebusa razem. Admiralicja podpisuje rozejm, którego kiedyś nie uznała.": "Vok's ships and the Colonies' fleet return from Erebus together. The Admiralty signs the truce it once refused to recognise.",
