	"Orbita Kharona": "Kharon Orbit",
	"ORBITA KHEPRI IV": "KHEPRI IV ORBIT",
	"Orbita należy do Kolonii": "The orbit belongs to the Colonies",
	"Orbita należy do Kolonii. Czas zejść na powierzchnię: Admiralicja okopała się w Dolinie Latarni — tam, gdzie zaczęła się kampania — i stawia baterie przeciwlotnicze. Kapsuły z floty, uderzenie i skan z orbity — reszta zależy od Ciebie. Artefakt pod piaskiem znów zaczął odpowiadać.": "The orbit belongs to the Colonies. Time to descend to the surface: the Admiralty has dug in at Lantern Valley — where the campaign began — and is setting up Flak Batteries. Pods from the fleet, an orbital strike and scan — the rest is up to you. The artifact beneath the sand has begun answering again.",
	"Orbita należy do wroga — brak kapsuł desantowych": "The orbit belongs to the enemy — no drop pods",
	"Orbita należy do wroga — brak kapsuł desantowych.": "The orbit belongs to the enemy — no drop pods.",
	"Orbita nasza": "The orbit is ours",
	"Orbita nasza. Kapsuły czekają w lukach — pora zejść na Eos.": "The orbit is ours. The pods are waiting in the bays — time to descend to Eos.",
	"Orbita Twoja:": "Orbit is yours:",
	"Orbita utracona": "Orbit lost",
	"Orbita utracona.": "Orbit lost.",
	"Orbita wroga: ma": "Orbit is the enemy's: they have",
	"Orbita zdobyta": "Orbit taken",
	"Orbita zdobyta.": "Orbit taken.",
	"Orbitalna stocznia Kolonii nad pustynną Eos, zajęta przez blokadę Admiralicji": "The Colonies' orbital shipyard above desert Eos, seized by the Admiralty blockade",
	"Orbitalna stocznia Kolonii nad pustynną Eos, zajęta przez blokadę Admiralicji. Długie pomosty doków tworzą przez środek pola bitwy pochylnię — w niej leżą najbogatsze złoża, a wyjścia prowadzą z obu końców i przez środek. Wieże cumownicze i pola asteroid wyznaczają korytarze na flankach. Burze słoneczne i deszcz odłamków.": "The Colonies' orbital shipyard above desert Eos, seized by the Admiralty blockade. The docks' long gantries form a slipway through the middle of the battlefield — the richest deposits lie within, with exits at both ends and through the centre. Mooring towers and asteroid fields mark out corridors on the flanks. Solar storms and debris showers.",
