	"Ostatnie zapasy z arsenału: metal i czołg. Wykorzystaj je dobrze.": "The last supplies from the arsenal: metal and a tank. Use them well.",
	"Ostrzał do 420 m i obrażenia w promieniu 75 m": "Fires up to 420 m with damage in a 75 m radius",
	"Ostrzał do 420 m i obrażenia w promieniu 75 m. Na dystansie poniżej 100 m siła bezpośredniego trafienia spada do 25%. Wymaga eskorty i fabryki.": "Fires up to 420 m with damage in a 75 m radius. Below 100 m, direct-hit strength drops to 25%. Requires an escort and a factory.",
