	"Parametry bazowe — koszty i atrybuty w bitwie uwzględniają frakcję oraz badania": "Base stats — in battle, costs and attributes reflect faction and research",
	"Parametry bazowe — koszty i atrybuty w bitwie uwzględniają frakcję oraz badania. Podglądy w powiększeniu.": "Base stats — in battle, costs and attributes reflect faction and research. Previews are enlarged.",
	"Parametry oddziału": "Squad parameters",
	"Parametry w obecnej pogodzie": "Stats in the current weather",
	"Parametry w obecnej pogodzie. Obrażenia przed premiami przeciw typom celów i ich osłonom; premie badań i frakcji uwzględnione. Porównaj typy, zaznaczając kilka jednostek.": "Stats in the current weather. Damage before bonuses against target types and their shields; research and faction bonuses included. Compare types by selecting several units.",
	"partii ·": "batches ·",
	"PAS ASTEROID HELION": "HELION ASTEROID BELT",
	"Pas barier": "Barrier Belt",
	"Pas Ikara · szlak komet": "Icarus Belt · comet trail",
	"Pas Ikara, przez który co kilka minut przelatują komety po stałych szlakach — jeden przecina pole bitwy z zachodu na wschód, drugi z północy na południe": "The Icarus Belt, crossed every few minutes by comets on fixed trails — one cuts the battlefield west to east, the other north to south",
	"Pas Ikara, przez który co kilka minut przelatują komety po stałych szlakach — jeden przecina pole bitwy z zachodu na wschód, drugi z północy na południe. Warkocz komety rani statki, które się w nim znajdą (najpierw osłony), ale odnawia gaz w polach, przez które przejdzie. Kto zna rozkład przelotów, ten wie, kiedy uderzyć. Lodowe bryły dają osłonę, burze jonowe i deszcz okruchów komet.": "The Icarus Belt, crossed every few minutes by comets on fixed trails — one cuts the battlefield west to east, the other north to south. A comet's tail damages ships caught in it (shields first) but replenishes gas in the fields it passes through. Know the schedule, and you know when to strike. Ice boulders provide cover; ion storms and comet fragment showers.",
	"Pasek u góry, panel boczny, pasek poleceń, menu i raporty; plansza bez zmian.": "The top bar, the side panel, the command bar, the menu and the reports; the board stays as it is.",
	"Pasek u góry, panel boczny, pasek poleceń, menu i raporty; plansza bez zmian. Nowa skala wraca do poprzedniej po 15 s, jeśli jej nie zachowasz.": "The top bar, the side panel, the command bar, the menu and the reports; the board stays as it is. A new size goes back to the previous one after 15 s unless you keep it.",
	"Paszczak wydmowy": "Dune Maw",
