	"POCZĄTEK": "THE BEGINNING",
	"Pod lodem Vesperu spoczywa zapomniane archiwum Kolonii": "Beneath the ice of Vesper lies a forgotten archive of the Colonies",
	"Pod lodem Vesperu spoczywa zapomniane archiwum Kolonii. Środek mapy zajmuje skuta lodem toń: lód udźwignie piechotę i lekkie pojazdy, ciężkie maszyny zwalniają, a silny wybuch przebija go na kilkadziesiąt sekund — kto stoi w przeręblu, ten ucierpi. Szczeliny lodowca schodzą ku jezioru z obu krańców, a przy brzegach sterczą ruiny stacji i zamarznięte narośle.": "Beneath the ice of Vesper lies a forgotten archive of the Colonies. The centre of the map is a frozen lake: the ice holds infantry and light vehicles, heavy machines slow down, and a powerful blast breaks through it for several dozen seconds — whoever stands in the hole will suffer. Glacier crevasses run down to the lake from both ends, and station ruins and frozen growths jut out along the shores.",
