	"Pogranicze Galaktyki — serwer lobby (WebSocket /lobby)": "Galactic Frontier — lobby server (WebSocket /lobby)",
	"Pogranicze Galaktyki rysuje planszę w 3D (WebGL), a ta przeglądarka lub karta graficzna go nie udostępnia. Włącz akcelerację sprzętową w ustawieniach przeglądarki, zaktualizuj przeglądarkę albo sterowniki karty graficznej i uruchom grę ponownie.": "Galactic Frontier draws its battlefield in 3D (WebGL), and this browser or graphics card does not provide it. Turn on hardware acceleration in the browser settings, update the browser or the graphics drivers, and start the game again.",
