	"pola siłowe nad statkami i stacjami odbijają odłamki — obrażenia od deszczu asteroid mniejsze o 80%.": "force fields over ships and stations deflect debris — asteroid shower damage reduced by 80%.",
	"Pole bitwy": "Battlefield",
	"Pole bitwy w sercu szkarłatnej mgławicy": "A battlefield in the heart of a crimson nebula",
	"Pole bitwy w sercu szkarłatnej mgławicy. Prawie wszędzie zalegają czerwone obłoki: statki w nich trudno trafić, ale ich osłony się nie odnawiają. Czysty korytarz biegnie po przekątnej od narożnika do narożnika — reszta to teren zasadzek między ciemnymi polami asteroid. Burze jonowe i rozbłyski gwiazdy ukrytej w mgławicy.": "A battlefield in the heart of a crimson nebula. Red clouds hang almost everywhere: ships inside them are hard to hit, but their shields do not regenerate. A clear corridor runs diagonally from corner to corner — the rest is ambush ground between dark asteroid fields. Ion storms and flares from a star hidden in the nebula.",
	"Pole bitwy. Zaznacz oddziały lewym przyciskiem, wydawaj rozkazy prawym.": "Battlefield. Select squads with the left button, give orders with the right.",
