	"poszerza strefę budowy (320); jednostki z kuźni wychodzą ze szczeliny przy kotwicy najbliższej punktu zbiórki; jednostki przy kotwicy przeskakują do innej.": "extends the build zone (320); forge units emerge from a rift at the anchor nearest the rally point; units at an anchor jump to another one.",
	"poszerza strefę budowy o promień 320 i widzi na 380. Oddziały z kuźni wychodzą ze szczeliny przy kotwicy najbliższej punktowi zbiórki. Jednostki przy kotwicy przeskakują do innej kotwicy (Do kotwicy, LPM na kotwicę docelową; co 8 s).": "extends the build zone by a radius of 320 and sees 380. Forge units emerge from a rift at the anchor nearest the rally point. Units at an anchor jump to another anchor (To Anchor, LMB on the target anchor; every 8 s).",
