	"Poziom": "Level",
	"poziom I Przyczółek. Rozbudowa w BADANIA / F2 za 300 metalu i 50 gazu, 30 s przy pełnej mocy. Poziom II Kolonia odblokowuje fabrykę, laboratorium, hangar i warsztat. Rozdziały I–III kampanii startują na poziomie II; szkolenie Próba kolonii zaczyna od Przyczółka. Poziom III Twierdza (z laboratorium; 600 metalu, 150 gazu, 100 kryształów, 45 s): centrum o 50% wytrzymalsze, +4 metalu/s i wybór jednej z dwóch doktryn frakcji — ostateczny. Kolonie: Logistyka mobilna albo Fortyfikacja przyczółków; Dominium: Ciężki ostrzał albo Silniejsze osłony; Rój: Nawała albo Pancerz chitynowy; Wartownicy: Światło Bramy albo Tarcze Otchłani. Wartownicy Otchłani: centrum (Rdzeń) daje +4 metalu/s i może przelecieć na nowe miejsce (Przenieś rdzeń, do 1100, co 120 s); w locie nie można go trafić ani nic w nim produkować.": "level I Outpost. Upgrade in RESEARCH / F2 for 300 metal and 50 gas, 30 s at full power. Level II Colony unlocks the factory, Laboratory, hangar and workshop. Campaign chapters I–III start at level II; the Colony Trial training starts from Outpost. Level III Fortress (requires a Laboratory; 600 metal, 150 gas, 100 crystals, 45 s): centre 50% tougher, +4 metal/s and a choice of one of the faction's two doctrines — final. Colonies: Mobile Logistics or Fortified Footholds; Dominion: Heavy Barrage or Stronger Shields; Swarm: Onslaught or Chitin Carapace; Wardens: Gatelight or Abyss Shields. Abyss Wardens: the centre (Core) gives +4 metal/s and can fly to a new location (Relocate Core, up to 1100, every 120 s); in flight it cannot be hit and nothing can be produced in it.",
	"Poziom startowy": "Starting level",
	"Poziom trudności": "Difficulty",
	"Poziom trudności kampanii": "Campaign difficulty",
	"pozostaje": "stands",
