	"PPM na rudzie — wydobycie; na uszkodzonym sojuszniku — naprawa.": "RMB on ore — mining; on a damaged ally — repair.",
	"PPM na rudzie: wydobycie": "RMB on ore: mining",
	"PPM na rudzie: wydobycie. Na uszkodzonym sojuszniku: naprawa.": "RMB on ore: mining. On a damaged ally: repair.",
	"PPM na własnej jednostce lub budynku — oddział trzyma się przy nim i go broni.": "RMB on your own unit or building — the squad stays close and defends it.",
	"PPM robotem": "RMB with a robot",
	"PPM robotem na złożu — wydobycie": "RMB on a deposit with a robot — mining",
	"PPM robotem na złożu — wydobycie. Bezczynne roboty wybierzesz klawiszem Z.": "RMB on a deposit with a robot — mining. Press Z to select idle robots.",
	"PPM robotem na złożu — wydobycie. Reaktor [C], laboratorium [N]. Home — cała mapa.": "RMB on a deposit with a robot — mining. Reactor [C], Laboratory [N]. Home — whole map.",
	"PPM wskazuje drugi koniec trasy — oddział krąży między nim a obecną pozycją, walcząc po drodze.": "RMB sets the other end of the route — the squad loops between it and its current position, fighting along the way.",
	"Pradawna dżungla olbrzymich drzew, które nocą świecą własnym światłem": "An ancient jungle of giant trees that glow with their own light at night",
	"Pradawna dżungla olbrzymich drzew, które nocą świecą własnym światłem. Środkiem mapy wije się świetlista rzeka z trzema brodami, a nad jej zakolami unoszą się porośnięte skalne wyspy. Gęstwina daje piechocie osłonę.": "An ancient jungle of giant trees that glow with their own light at night. A luminous river with three fords winds through the middle of the map, and overgrown rock islands float above its bends. The thick undergrowth gives infantry cover.",
