	"Pryzmat": "Prism",
	"Pryzmat Wartowników (wielka kuźnia, 200): wiązka narasta, dopóki trzyma ten sam cel — każde trafienie +25%, do ×2,5": "Warden Prism (Great Forge, 200): the beam builds up while it holds the same target — each hit +25%, up to ×2",
	"Pryzmat Wartowników (wielka kuźnia, 200): wiązka narasta, dopóki trzyma ten sam cel — każde trafienie +25%, do ×2,5. Zmiana celu zeruje wiązkę; najlepszy przeciw ciężkim pojazdom i budynkom.": "Warden Prism (Great Forge, 200): the beam builds up while it holds the same target — each hit +25%, up to ×2.5. Switching targets resets the beam; best against heavy vehicles and buildings.",
	"Pryzmat Wartowników: wiązka, której obrażenia rosną o 25% z każdym kolejnym trafieniem tego samego celu (do +150%)": "Warden Prism: a beam whose damage grows by 25% with each consecutive hit on the same target (up to +150%)",
	"Pryzmat Wartowników: wiązka, której obrażenia rosną o 25% z każdym kolejnym trafieniem tego samego celu (do +150%).": "Warden Prism: a beam whose damage grows by 25% with each consecutive hit on the same target (up to +150%).",
