	"Przeciągnij mur pod dowolnym kątem. Alt + przeciągnięcie tworzy okrąg.": "Drag a wall at any angle. Alt + drag makes a circle.",
	"Przeciążam rdzeń": "Overloading the core",
	"Przeciążam rdzeń. Za 20 sekund Serce popiołu wybuchnie — wycofaj wszystkich z promienia 380!": "Overloading the core. In 20 seconds the Heart of Ash will blow — pull everyone out of the 380 radius!",
	"PRZECIĄŻENIE": "OVERLOAD",
	"Przeciążenie · tarcza wróci za": "Overload · shield returns in",
	"Przeciążenie rdzenia": "Core overload",
	"PRZECIĄŻENIE RDZENIA": "CORE OVERLOAD",
	"PRZECIĄŻENIE ZA": "OVERLOAD IN",
	"Przeciążenie za 20 s niszczy wszystko w promieniu 380": "An overload in 20 s destroys everything within radius 380",
	"Przeciążenie za 20 s niszczy wszystko w promieniu 380. Wieże Dominium tracą 50% PW, odzysk 400 metalu. Cel dodatkowy: bez strat od wybuchu.": "An overload in 20 s destroys everything within radius 380. Dominion towers lose 50% HP, 400 metal salvaged. Bonus objective: no losses from the blast.",
	"Przeciw piechocie": "Anti-infantry",
	"Przeciw pojazdom": "Anti-vehicle",
