	"przeciwnik": "enemy",
	"Przeciwnik": "Enemy",
	"PRZECIWNIK": "ENEMY",
	"Przeciwnik powoli rozbudowuje bazę (4 roboty, jedna wieżyczka, fabryka dopiero po 7 minutach), reaguje z opóźnieniem, atakuje rzadko i zawsze centrum dowodzenia": "The enemy expands its base slowly (4 robots, one turret, a factory only after 7 minutes), reacts with a delay, attacks rarely and always targets the Command Centre",
	"Przeciwnik powoli rozbudowuje bazę (4 roboty, jedna wieżyczka, fabryka dopiero po 7 minutach), reaguje z opóźnieniem, atakuje rzadko i zawsze centrum dowodzenia. Nie dobiera jednostek pod Twoją armię.": "The enemy expands its base slowly (4 robots, one turret, a factory only after 7 minutes), reacts with a delay, attacks rarely and always targets the Command Centre. It does not counter your army composition.",
	"Przeciwnik rozbudowuje bazę i wydobywa rudę": "The enemy is expanding its base and mining ore",
	"Przeciwnik rozbudowuje bazę i wydobywa rudę. Atak nastąpi, gdy zbierze wystarczające siły.": "The enemy is expanding its base and mining ore. It will attack once it has gathered enough forces.",
	"Przeciwnik szybko rozwija gospodarkę (8 robotów, magazyn przy dalszym złożu), buduje fabrykę po 2 minutach, trzy wieżyczki i hangar, reaguje co sekundę, dobiera jednostki przeciw Twojej armii, atakuje najsłabiej bronione cele, nęka roboty szybkimi oddziałami i wycofuje przegrane ataki": "The enemy grows its economy fast (8 robots, a depot by a farther deposit), builds a factory after 2 minutes, three turrets and a hangar, reacts every second, picks units to counter your army, attacks the weakest-defended targets, harasses robots with fast squads and pulls back failing attacks",
	"Przeciwnik szybko rozwija gospodarkę (8 robotów, magazyn przy dalszym złożu), buduje fabrykę po 2 minutach, trzy wieżyczki i hangar, reaguje co sekundę, dobiera jednostki przeciw Twojej armii, atakuje najsłabiej bronione cele, nęka roboty szybkimi oddziałami i wycofuje przegrane ataki. Ulepsza pancerz i broń, po ok. 8 minutach ma Twierdzę i doktrynę dobraną do sytuacji; dwa patrole, eskorta wydobycia i artylerii w natarciu.": "The enemy grows its economy fast (8 robots, a depot by a farther deposit), builds a factory after 2 minutes, three turrets and a hangar, reacts every second, picks units to counter your army, attacks the weakest-defended targets, harasses robots with fast squads and pulls back failing attacks. It upgrades armour and weapons, has a Fortress after about 8 minutes and a doctrine suited to the situation; two patrols, mining escorts and artillery in the advance.",
	"Przeciwnik utrzymuje 6 robotów, stawia fabrykę po ok": "The enemy keeps 6 robots, builds a factory after about 3 minutes and a second Barracks, takes nearby relays, defends its mines and attacks your nearest building",
	"Przeciwnik utrzymuje 6 robotów, stawia fabrykę po ok. 3 minutach i drugie koszary, zajmuje pobliskie przekaźniki, broni kopalń, a do ataku wybiera najbliższy Twój budynek. Częściowo dobiera jednostki przeciw Twojej armii; po 9 minutach ulepsza pancerz, po ok. 11 rozbudowuje centrum do Twierdzy i przyjmuje doktrynę. Patroluje drogę do przekaźnika i osłania dalekie wydobycie.": "The enemy keeps 6 robots, builds a factory after about 3 minutes and a second Barracks, takes nearby relays, defends its mines and attacks your nearest building. It partly picks units to counter your army; after 9 minutes it upgrades armour, after about 11 it upgrades its centre to a Fortress and adopts a doctrine. It patrols the road to the relay and guards distant mining.",
	"Przeciwnik w pełnej sile": "Enemy at full strength",
	"Przeciwnik w pełnej sile.": "Enemy at full strength.",
	"Przeciwnik zbiera surowce, buduje i płaci za każdą jednostkę": "The enemy gathers resources, builds and pays for every unit",
	"Przeciwnik zbiera surowce, buduje i płaci za każdą jednostkę.": "The enemy gathers resources, builds and pays for every unit.",
