	"PRZESTRZEŃ MIĘDZY ŚWIATAMI": "THE SPACE BETWEEN WORLDS",
	"Przetrwaj": "Survive",
	"Przetrwaj 10 minut": "Survive 10 minutes",
	"Przetrwaj 10 minut.": "Survive 10 minutes.",
	"Przetrwaj 10 minut. Desanty są o 25% liczniejsze i przychodzą o 15% częściej; na start dostajesz 500 metalu więcej i dwie wieżyczki przy bazie. Zniszczenie wszystkich wrogich centrów kończy obronę wcześniej.": "Survive 10 minutes. Landings are 25% larger and come 15% more often; you start with 500 extra metal and two turrets by the base. Destroying all enemy centres ends the defence early.",
	"Przetrwaj desant Admiralicji": "Survive the Admiralty landing",
	"Przetrwaj desant Admiralicji (kapsuły Vok:": "Survive the Admiralty landing (Vok's pods:",
	"Przetrwaj desant Admiralicji, potem pokonaj Vok — zniszcz jej kwaterę": "Survive the Admiralty landing, then defeat Vok — destroy her headquarters",
	"Przetrwaj desant Admiralicji, potem pokonaj Vok — zniszcz jej kwaterę. Dodatkowo: zestrzel kapsuły Vok (2, na trudnym 3).": "Survive the Admiralty landing, then defeat Vok — destroy her headquarters. Bonus: shoot down Vok's pods (2, on Hard 3).",
	"Przetrwaj jak najdłużej — fale nie kończą się": "Survive as long as you can — the waves never end",
	"Przetrwaj jak najdłużej — fale nie kończą się.": "Survive as long as you can — the waves never end.",
