	"Przewozi 4 piechurów lub rakietowców": "Carries 4 infantrymen or Rocketeers",
	"Przewozi 4 piechurów lub rakietowców. PPM piechotą na transporterze: załadunek; przycisk Wyładuj: desant. Załoga liczy się do limitu armii. Po zniszczeniu wysiada z 50% pozostałych PW, jeśli jest wolny teren.": "Carries 4 infantrymen or Rocketeers. RMB with infantry on the transport: load; Unload button: deploy. The crew counts towards the army limit. When destroyed, the crew disembarks with 50% of their remaining HP if there is free ground.",
	"PRZEZ BLOKADĘ": "THROUGH THE BLOCKADE",
