	"Przy horyzoncie zdarzeń Erebusa Brama pękła i runęła w ciemność": "At the event horizon of Erebus the Gate cracked and plunged into darkness",
	"Przy horyzoncie zdarzeń Erebusa Brama pękła i runęła w ciemność. Światło Wartowników zgasło, a Głos Bramy umilkł w pół słowa.": "At the event horizon of Erebus the Gate cracked and plunged into darkness. The Wardens' light went out, and the Voice of the Gate fell silent mid-word.",
	"Przy skałach, murach i zamkniętych bramach otrzymuje o 30% mniej obrażeń dystansowych": "Takes 30% less ranged damage next to rocks, walls and closed gates",
