	"Pustynia pod dwoma słońcami": "A desert under two suns",
	"Pustynia pod dwoma słońcami. Wysokie płaskowyże tworzą kaniony, a przez środek mapy ciągnie się kadłub rozbitego krążownika z przejściami między pękniętymi sekcjami. Kryształy z jego rdzeni wciąż świecą w piasku; w wydmach czają się paszczaki.": "A desert under two suns. High plateaus form canyons, and the hull of a wrecked cruiser stretches across the middle of the map, with passages between its broken sections. Crystals from its cores still glow in the sand; Dune Maws lurk in the dunes.",
