	"RATUJ GARNIZON VARNA": "RESCUE VARN'S GARRISON",
	"Razem przetrwaliście": "Together you survived",
	"Rdzenie wskazały źródło blokady — kompleks Hefajstos na Vulkanie IX": "The cores have revealed the source of the blockade — the Hephaestus Complex on Vulkan IX",
	"Rdzenie wskazały źródło blokady — kompleks Hefajstos na Vulkanie IX.": "The cores have revealed the source of the blockade — the Hephaestus Complex on Vulkan IX.",
	"Rdzenie z Vesperu doprowadziły Kolonie do źródła blokady: kompleksu Hefajstos, który wysysa energię planety i doprowadza faunę do szału": "The cores from Vesper led the Colonies to the source of the blockade: the Hephaestus complex, which drains the planet's energy and drives the fauna into a frenzy",
	"Rdzenie z Vesperu doprowadziły Kolonie do źródła blokady: kompleksu Hefajstos, który wysysa energię planety i doprowadza faunę do szału. Przejmij węzły sterujące i zdecyduj: zniszczyć instalację czy odłączyć ją i ewakuować personel. Następnie rozbij centrum Dominium.": "The cores from Vesper led the Colonies to the source of the blockade: the Hephaestus complex, which drains the planet's energy and drives the fauna into a frenzy. Seize the control nodes and decide: destroy the installation, or disconnect it and evacuate the staff. Then smash the Dominion centre.",
	"Rdzeń": "Core",
	"Rdzeń danych": "Data Core",
	"RDZEŃ DANYCH": "DATA CORE",
	"Rdzeń danych bezpieczny w bazie": "The data core is safe at the base",
	"Rdzeń danych bezpieczny w bazie. Lira zaczyna deszyfrowanie.": "The data core is safe at the base. Lira begins decryption.",
	"Rdzeń Hefajstosa gaśnie": "The Hephaestus core goes dark",
	"Rdzeń Hefajstosa gaśnie. Transporter wywozi techników kompleksu — ludzi, którzy pracowali pod przymusem.": "The Hephaestus core goes dark. A transport carries out the complex technicians — people who worked under duress.",
	"Rdzeń Hefajstosa przeciążony": "The Hephaestus core overloads",
	"Rdzeń Hefajstosa przeciążony. Kompleks, który wysysał energię planety, znika w ogniu.": "The Hephaestus core overloads. The complex that drained the planet's energy vanishes in fire.",
	"Rdzeń kompleksu Hefajstos (akt II, rozdział VI)": "The core of the Hephaestus Complex (Act II, Chapter VI)",
	"Rdzeń kompleksu Hefajstos (akt II, rozdział VI). Nie można go ostrzelać — o jego losie decyduje przejęcie trzech węzłów sterujących.": "The core of the Hephaestus Complex (Act II, Chapter VI). It cannot be attacked — its fate is decided by capturing the three control nodes.",
	"Rdzeń może znów przelecieć za": "The Core can relocate again in",
	"Rdzeń ponownie na pokładzie": "The core is back on board",
	"Rdzeń ponownie na pokładzie. Kieruj się na lądowisko.": "The core is back on board. Head for the landing zone.",
	"Rdzeń sondy ujawnia, dokąd Dominium wywiozło rdzenie dawnej sieci: na Vesper": "The probe core reveals where the Dominion took the cores of the old network: to Vesper",
	"Rdzeń sondy ujawnia, dokąd Dominium wywiozło rdzenie dawnej sieci: na Vesper.": "The probe core reveals where the Dominion took the cores of the old network: to Vesper.",
