	"Rezerwa": "Reserve",
	"Rezonator": "Resonator",
	"Rezonator stoi przy złożu rudy, kryształów lub przy własnym przekaźniku": "A Resonator must stand by an ore or crystal deposit, or by your own relay",
	"Rezonator stoi przy złożu rudy, kryształów lub przy własnym przekaźniku.": "A Resonator must stand by an ore or crystal deposit, or by your own relay.",
	"Rezonator Wartowników (220): stawiany przy złożu rudy (5 metalu/s), kryształów (3 metalu/s i 0,4 kryształu/s) albo przy własnym przekaźniku (5 metalu/s)": "Wardens Resonator (220): placed by an ore deposit (5 metal/s), crystals (3 metal/s and 0",
	"Rezonator Wartowników (220): stawiany przy złożu rudy (5 metalu/s), kryształów (3 metalu/s i 0,4 kryształu/s) albo przy własnym przekaźniku (5 metalu/s). Zamiast robotów górniczych — Tkacze nie wydobywają rudy.": "Wardens Resonator (220): placed by an ore deposit (5 metal/s), crystals (3 metal/s and 0.4 crystals/s) or by your own relay (5 metal/s). Replaces Mining Robots — Weavers do not mine ore.",
	"Rezonator Wartowników: przy złożu rudy (5 metalu/s), kryształów (3 metalu i 0,4 kryształu/s) albo własnym przekaźniku (5 metalu/s) — zamiast robotów górniczych": "Warden Resonator: at an ore deposit (5 metal/s), a crystal deposit (3 metal and 0",
	"Rezonator Wartowników: przy złożu rudy (5 metalu/s), kryształów (3 metalu i 0,4 kryształu/s) albo własnym przekaźniku (5 metalu/s) — zamiast robotów górniczych.": "Warden Resonator: at an ore deposit (5 metal/s), a crystal deposit (3 metal and 0.4 crystals/s) or your own relay (5 metal/s) — instead of mining robots.",
	"Robot": "Robot",
	"Robot górniczy": "Mining Robot",
	"Robot nie może dotrzeć do celu i przerwał zadanie": "The robot cannot reach its destination and has abandoned the task",
	"Robot nie może dotrzeć do celu i przerwał zadanie.": "The robot cannot reach its destination and has abandoned the task.",
	"Robot przewozi 30 rudy do centrum lub ukończonego magazynu": "A robot carries 30 ore to the centre or a finished depot",
	"Robot przewozi 30 rudy do centrum lub ukończonego magazynu. G — magazyn (120 metalu, 10 s), X — ekstraktor (160 metalu, 12 s). Z wybiera bezczynne roboty. Gaz jest skończony i wymaga operatora. L — większe ładownie: 150 metalu + 50 gazu, 25 s, wymaga magazynu; zwiększa ładunek do 60. Badanie można anulować z pełnym zwrotem obu surowców. Utrata wymaganego budynku wstrzymuje badanie. Centrum zapewnia 8 metalu/s, własny przekaźnik kolejne 5/s. T/B/V — budowa wieżyczki, koszar lub fabryki. Fabryka pozwala zbadać broń (+25% obrażeń) i pancerz (−20% otrzymanych obrażeń), każde za 250 metalu i 25 s. U/I — badania.": "A robot carries 30 ore to the centre or a finished depot. G — depot (120 metal, 10 s), X — extractor (160 metal, 12 s). Z selects idle robots. Gas is finite and needs an operator. L — Enlarged Holds: 150 metal + 50 gas, 25 s, requires a depot; raises the load to 60. Research can be cancelled with a full refund of both resources. Losing the required building pauses research. The centre provides 8 metal/s, your own relay another 5/s. T/B/V — build a turret, Barracks or factory. The factory lets you research weapons (+25% damage) and armour (−20% damage taken), each for 250 metal and 25 s. U/I — research.",
