	"Roboty przewożą rudę do bazy": "Robots haul ore to the base",
	"Roboty przewożą rudę do bazy. Zbuduj fabrykę, ulepsz armię i odkrywaj teren. Przejmuj przekaźniki, aby tworzyć nowe przyczółki.": "Robots haul ore to the base. Build a factory, upgrade your army and explore the map. Capture relays to set up new outposts.",
