	"RÓJ · BEZ POSIŁKÓW": "SWARM · NO REINFORCEMENTS",
	"Rój czerpał energię z kompleksu — bez niej gniazda i Serce Roju mają o 25% mniej wytrzymałości, a rdzenie z ruin dają 250 metalu na start każdego rozdziału": "The Swarm drew energy from the complex — without it, the nests and the Heart of the Swarm have 25% less durability, and cores from the ruins give 250 metal at the start of each chapter",
	"Rój czerpał energię z kompleksu — bez niej gniazda i Serce Roju mają o 25% mniej wytrzymałości, a rdzenie z ruin dają 250 metalu na start każdego rozdziału. Varn stracił elektrownię i nie przyśle posiłków ani planów.": "The Swarm drew energy from the complex — without it, the nests and the Heart of the Swarm have 25% less durability, and cores from the ruins give 250 metal at the start of each chapter. Varn lost his power plant and will send neither reinforcements nor plans.",
	"Rój go zabiera! Przechwyćcie niosącego, zanim zniknie w grotach!": "The Swarm is taking it! Intercept the bearer before it vanishes into the caves!",
	"Rój Kryształowy": "Crystal Swarm",
	"Rój rozlał się po Nivalis i odciął garnizon Dominium": "The Swarm has spread across Nivalis and cut off a Dominion garrison",
	"Rój rozlał się po Nivalis i odciął garnizon Dominium. Kmdr Varn prosi o pomoc — dawny wróg, dziś jedyny sojusznik. Na środku przełęczy stoi Szczyt: z niego zagłuszycie rezonans, którym Rój się porozumiewa.": "The Swarm has spread across Nivalis and cut off a Dominion garrison. Cdr. Varn asks for help — a former enemy, now your only ally. In the middle of the pass stands the Summit: from there you can jam the resonance the Swarm uses to communicate.",
	"Rój również poluje na artefakt": "The Swarm is also hunting the artifact",
	"Rój trzyma się planu poziomu trudności: tanie jednostki, stała presja": "The Swarm sticks to the difficulty plan: cheap units, constant pressure",
