	"s, gdy w pobliżu nie ma wroga; niosący porusza się o 30% wolniej i jest zawsze widoczny. Gdy zginie lub wsiądzie do transportera, artefakt upada na ziemię. Przeciwnik również wysyła ekspedycje. Zniszczenie wszystkich wrogich centrów nadal daje zwycięstwo.": "s when no enemy is nearby; the carrier moves 30% slower and is always visible. If they die or board a transport, the artefact falls to the ground. The enemy sends expeditions too. Destroying all enemy centres still wins the game.",
