	"sekund": "seconds",
	"Serca bijącego pod rzekami magmy Pyrrhosa. Varn przekazuje Koloniom dostęp do stacji orbitalnej. To ostatnia bitwa aktu — zniszcz Serce, zanim Rój obudzi się na dobre.": "the Heart beating beneath the magma rivers of Pyrrhos. Varn gives the Colonies access to the Orbital Uplink. This is the last battle of the act — destroy the Heart before the Swarm fully awakens.",
	"Serce Dominium": "Heart of the Dominion",
	"SERCE GAŚNIE": "THE HEART GOES DARK",
	"Serce popiołu": "Heart of Ash",
	"SERCE POPIOŁU": "HEART OF ASH",
	"Serce popiołu przestało istnieć": "The Heart of Ash is no more",
	"Serce popiołu przestało istnieć. Dominium straciło źródło energii blokady, lecz razem z kompleksem zniknęła wiedza o sieci. Koss i dwoje techników zdążyli uciec przed wybuchem — reszta nie. Pogranicze jest wolne — i ostrożne wobec własnej siły.": "The Heart of Ash is no more. The Dominion has lost the blockade's power source, but the knowledge of the network vanished with the complex. Koss and two technicians escaped the blast — the rest did not. The Frontier is free — and wary of its own strength.",
	"Serce popiołu zniszczone": "Heart of Ash destroyed",
	"Serce popiołu zniszczone. Fala przeciążenia uszkodziła wieże Dominium; odzyskaliśmy 400 metalu ze złomu.": "Heart of Ash destroyed. The overload wave damaged the Dominion towers; we salvaged 400 metal from the scrap.",
	"Serce Roju": "Heart of the Swarm",
	"SERCE ROJU": "HEART OF THE SWARM",
	"SERCE ROJU · AKTYWNOŚĆ": "HEART OF THE SWARM · ACTIVITY",
	"Serce Roju bije pod rzekami magmy": "The Heart of the Swarm beats beneath the magma rivers",
	"Serce Roju bije pod rzekami magmy. Każde uderzenie odbija się echem w artefaktach.": "The Heart of the Swarm beats beneath the magma rivers. Every beat echoes through the artifacts.",
	"Serce Roju bije pod rzekami magmy. Każde uderzenie słychać w artefaktach.": "The Heart of the Swarm beats beneath the magma rivers. Every beat can be heard in the artifacts.",
	"Serce Roju gaśnie, a wraz z nim milkną artefakty w całym pograniczu": "The Heart of the Swarm fades, and with it the artifacts fall silent across the Frontier",
	"Serce Roju gaśnie, a wraz z nim milkną artefakty w całym pograniczu.": "The Heart of the Swarm fades, and with it the artifacts fall silent across the Frontier.",
	"Serce Roju karmiło się energią Hefajstosa": "The Heart of the Swarm fed on Hephaestus's energy",
	"Serce Roju karmiło się energią Hefajstosa. Bez niej bije słabiej — wykorzystajmy to.": "The Heart of the Swarm fed on Hephaestus's energy. Without it, it beats weaker — let's exploit that.",
	"Serce Roju pęka": "The Heart of the Swarm cracks",
	"Serce Roju pęka. Fiolet gaśnie pod rzekami magmy, a Rój rozpada się w pył.": "The Heart of the Swarm cracks. The violet fades beneath the magma rivers, and the Swarm crumbles to dust.",
	"Serce Roju spało pod magmą Pyrrhosa": "The Heart of the Swarm slept beneath the magma of Pyrrhos",
	"Serce Roju spało pod magmą Pyrrhosa. Dr Tessa została na jego skraju, by pilnować, żeby już się nie obudziło.": "The Heart of the Swarm slept beneath the magma of Pyrrhos. Dr Tessa stayed at its edge to make sure it never woke again.",
	"Serce Roju ucichło": "The Heart of the Swarm fell silent",
	"Serce Roju ucichło. Kolonie i Dominium, każde własną drogą, podpisały nad Pyrrhosem rozejm.": "The Heart of the Swarm fell silent. The Colonies and the Dominion, each in its own way, signed a truce over Pyrrhos.",
	"Serce Roju ucichło. Nad Pyrrhosem komandor Varn i Kolonie podpisali rozejm.": "The Heart of the Swarm fell silent. Over Pyrrhos, Commander Varn and the Colonies signed a truce.",
	"Serce Roju ucichło. Wspólne dowództwo z Varnem przetrwało bitwę o Pyrrhos, a Dominium podpisało rozejm z Koloniami.": "The Heart of the Swarm fell silent. The joint command with Varn survived the battle for Pyrrhos, and the Dominion signed a truce with the Colonies.",
	"SERCE ROJU: BRAK SYGNAŁU": "HEART OF THE SWARM: NO SIGNAL",
	"Serce wytrzymalsze o 50%": "Heart 50% tougher",
