	"siatka zrujnowanych kwartałów przecięta wąskimi ulicami, z szeroką aleją i placem cytadeli w środku. Kto trzyma skrzyżowania, ten trzyma złoża. Na dwóch placach dymią stare wieże przetwarzania, a na przedmieściach gnieżdżą się pajęczaki.": "a grid of ruined blocks cut by narrow streets, with a broad avenue and a citadel square at its heart. Whoever holds the crossroads holds the deposits. Old processing towers smoke on two squares, and spiders nest in the outskirts.",
