	"Strażnik Wartowników (wielka kuźnia, 300): ciężki": "Abyss Warden (Great Forge, 300): heavy",
	"Strażnik Wartowników (wielka kuźnia, 300): ciężki. Umiejętność Faza (⇧Q): 3 s bez otrzymywania obrażeń, ale i bez strzelania; odnowienie 18 s. Dwóch strażników obok siebie scala się w konstrukt (przycisk Scal).": "Abyss Warden (Great Forge, 300): heavy. Phase ability (⇧Q): 3 s without taking damage, but also without firing; cooldown 18 s. Two Wardens side by side merge into a Construct (Merge button).",
