	"SYGNAŁ NIEZNANY · ŹRÓDŁO: SZCZELINA": "UNKNOWN SIGNAL · SOURCE: RIFT",
	"Sygnał pochodzi z obozu na północnym wschodzie": "The signal comes from a camp to the north-east",
	"Sygnał pochodzi z obozu na północnym wschodzie. Za skalnym grzbietem są jamy paszczaków — przejścia w środku i na południu są pilnowane przez nie, północne przez posterunek Dominium.": "The signal comes from a camp to the north-east. Beyond the rocky ridge lie the maws' pits — the middle and southern passages are guarded by them, the northern one by a Dominion outpost.",
	"SYGNAŁ PRZYCHODZĄCY / KHEPRI IV": "INCOMING SIGNAL / KHEPRI IV",
	"Sygnał spod piasku": "Signal from Beneath the Sand",
	"sygnał Tessy": "Tessa's signal",
	"SYGNAŁ UTRACONY": "SIGNAL LOST",
	"Sygnał z Khepri ujawnił trasę konwoju": "The signal from Khepri revealed the convoy route",
	"Sygnał z Khepri ujawnił trasę konwoju. Zabezpiecz lodowy szlak, uruchom dwa magazyny zaopatrzenia i odbierz Dominium port przeładunkowy.": "The signal from Khepri revealed the convoy route. Secure the ice trail, bring two supply depots online and take the transfer port from the Dominion.",
	"SYGNAŁ Z POWIERZCHNI": "SIGNAL FROM THE SURFACE",
	"Symulacja zatrzymana": "Simulation paused",
	"SYMULACJA ZATRZYMANA": "SIMULATION PAUSED",
	"Symulacja zatrzymana. Twoje oddziały czekają na rozkazy.": "Simulation paused. Your units are awaiting orders.",
	"Symulacje graczy przestały się zgadzać — bitwa została przerwana": "The players' simulations no longer match — the battle has been stopped",
	"Symulacje graczy przestały się zgadzać — bitwa została przerwana. Zgłoś to twórcy gry (mapa, frakcje, co działo się tuż przed).": "The players' simulations no longer match — the battle has been stopped. Please report it to the developer (map, factions, what happened just before).",
	"SYMULATOR BITEW / KONFIGURACJA": "BATTLE SIMULATOR / CONFIGURATION",
