	"Szeroka kotlina Eos, nad którą górowała latarnia Kolonii": "A wide basin on Eos, once overlooked by the Colonies' beacon",
	"Szeroka kotlina Eos, nad którą górowała latarnia Kolonii. Niskie grzbiety wydm i płytkie wąwozy mają wiele przejść, a ruiny dawnej osady i skalne wzgórza dają osłonę. Oazy przy obu krańcach doliny i bogate złoża w jej środku zachęcają do szybkiej ekspansji.": "A wide basin on Eos, once overlooked by the Colonies' beacon. Low dune ridges and shallow ravines offer many passages, while the ruins of an old settlement and rocky hills provide cover. Oases at both ends of the valley and rich deposits in its centre invite rapid expansion.",
	"Sześcioro techników musi dotrzeć na lądowisko — co najmniej czworo": "Six technicians must reach the landing zone — at least four",
	"Sześcioro techników musi dotrzeć na lądowisko — co najmniej czworo. Pajęczaki wpadną w szał. Premia: plany od techników — pancerz kompozytowy (gdy już go masz: broń plazmowa, a gdy i ją — 300 metalu). Cel dodatkowy: ocal wszystkich.": "Six technicians must reach the landing zone — at least four. The spiders will go berserk. Bonus: blueprints from the technicians — Composite Armour (if you already have it: Plasma Weapons; if you have both — 300 metal). Bonus objective: save them all.",
