	"świat scenariuszy": "scenario world",
	"Świat zawieszonych gór i bezdennych rozpadlin": "A world of suspended mountains and bottomless chasms",
	"Świat zawieszonych gór i bezdennych rozpadlin. Krzyż przepaści dzieli planetę na cztery płaskowyże połączone wąskimi skalnymi mostami. Kto utrzyma mosty, ten dyktuje tempo bitwy. Lotnictwo przelatuje nad przepaściami bez przeszkód.": "A world of suspended mountains and bottomless chasms. A cross of abysses splits the planet into four plateaus joined by narrow rock bridges. Whoever holds the bridges dictates the pace of battle. Aircraft fly over the chasms unhindered.",
