	"Tarcza": "Shield",
	"Tarcza nad budynkami · 35 mocy": "Shield over buildings · 35 power",
	"Tarcza nad budynkami w promieniu 230 pochłania 70% obrażeń (pojemność 700)": "A shield over buildings within 230 absorbs 70% of damage (capacity 700)",
	"Tarcza nad budynkami w promieniu 230 pochłania 70% obrażeń (pojemność 700). Odnawia się 25/s po 4 s spokoju. Wyczerpana — przeciążenie na 12 s, potem start od 25%. Nie chroni jednostek. Pobór 35 mocy. Wymaga Kolonii.": "A shield over buildings within 230 absorbs 70% of damage (capacity 700). Recharges 25/s after 4 s of calm. When depleted — overload for 12 s, then restarts at 25%. Does not protect units. Draws 35 power. Requires Colony.",
	"Tarcze na jednostkach i budynkach": "Shields on units and buildings",
	"Tarcze na jednostkach i budynkach; lewitacja; dochód z Rezonatorów zamiast górników; centrum może przelecieć.": "Shields on units and buildings; levitation; income from Resonators instead of miners; the centre can fly.",
	"Tarcze Otchłani": "Abyss Shields",
	"te rdzenie zasilą całą sieć. Nie możemy stracić więcej niż jednego.": "these cores will power the whole network. We can't lose more than one.",
	"te same zasady i frakcje, nowy układ mapy. Obaj gracze muszą się zgodzić.": "same rules and factions, a new map layout. Both players must agree.",
	"Team": "Team",
	"Technicy Kossa odbudowali Hefajstos": "Koss's technicians rebuilt Hephaestus",
	"Technicy Kossa odbudowali Hefajstos. Kompleks, który wysysał energię planety, dziś zasila Kolonie.": "Koss's technicians rebuilt Hephaestus. The complex that once drained the planet's energy now powers the Colonies.",
	"Technicy uratowani z Hefajstosa przekazali nam plany niszczyciela czołgów Dominium": "The technicians rescued from Hephaestus gave us the plans for the Dominion Tank Destroyer",
	"Technicy uratowani z Hefajstosa przekazali nam plany niszczyciela czołgów Dominium. Fabryka może je budować.": "The technicians rescued from Hephaestus gave us the plans for the Dominion Tank Destroyer. The factory can build them.",
	"Technicy z Hefajstosa i żołnierze Varna świętują razem z Kolonistami — dług został spłacony z nawiązką": "The Hephaestus technicians and Varn's soldiers celebrate together with the Colonists — the debt has been repaid with interest",
	"Technicy z Hefajstosa i żołnierze Varna świętują razem z Kolonistami — dług został spłacony z nawiązką.": "The Hephaestus technicians and Varn's soldiers celebrate together with the Colonists — the debt has been repaid with interest.",
	"Technik jest ranny! Osłoń go, zanim go stracimy": "The technician is wounded! Cover him before we lose him",
	"Technik jest ranny! Osłoń go, zanim go stracimy.": "The technician is wounded! Cover him before we lose him.",
	"Technik kompleksu": "Complex Technician",
	"Technik kompleksu Hefajstos (akt II, rozdział VI)": "A technician of the Hephaestus Complex (Act II, Chapter VI)",
	"Technik kompleksu Hefajstos (akt II, rozdział VI). Pojawia się po decyzji o odłączeniu instalacji. Odprowadź go pieszo lub transporterem na lądowisko.": "A technician of the Hephaestus Complex (Act II, Chapter VI). Appears after the decision to shut down the facility. Escort him on foot or by transport to the landing pad.",
	"Technik nie żyje": "A technician is dead",
	"Technik nie żyje. Nie zostawiajcie reszty!": "A technician is dead. Don't leave the rest behind!",
	"Technik z Eos uruchomi starą stację uplink na szlaku — doprowadźmy go żywego": "The technician from Eos will restart the old uplink station on the trail — let's get him there alive",
	"Technik z Eos uruchomi starą stację uplink na szlaku — doprowadźmy go żywego. Z orbitą łatwiej będzie zdobyć Twierdzę.": "The technician from Eos will restart the old uplink station on the trail — let's get him there alive. With the orbit, taking the Fortress will be easier.",
	"Technik zginął": "The technician is dead",
	"Technik zginął na Popielnym Szlaku — stacja uplink nie zostanie uruchomiona": "The technician died on the Ash Trail — the uplink station will not be activated",
	"Technik zginął na Popielnym Szlaku — stacja uplink nie zostanie uruchomiona. Spróbuj ponownie i osłaniaj konwój.": "The technician died on the Ash Trail — the uplink station will not be activated. Try again and protect the convoy.",
	"Technik zginął. Misja nieudana.": "The technician is dead. Mission failed.",
