	"Tu admirał Selen Vok": "This is Admiral Selen Vok",
	"Tu admirał Selen Vok. Orbita Eos jest zamknięta. Rozejm Varna nic nie znaczy — zdrajca nie podpisuje się w imieniu Dominium.": "This is Admiral Selen Vok. Eos orbit is closed. Varn's truce means nothing — a traitor does not sign in the Dominion's name.",
	"Tu admirał Selen Vok. Varn to zdrajca, a jego rozejm to papier. Każdy statek Kolonii na tej orbicie zostanie zatopiony.": "This is Admiral Selen Vok. Varn is a traitor, and his truce is just paper. Every Colony ship in this orbit will be sunk.",
	"Tu doktor Mira Tessa… jeśli ktoś to słyszy — jesteśmy pod piaskiem Khepri, w starej sondzie": "This is Dr Mira Tessa… if anyone can hear this — we're under the sands of Khepri, in an old probe",
	"Tu doktor Mira Tessa… jeśli ktoś to słyszy — jesteśmy pod piaskiem Khepri, w starej sondzie.": "This is Dr Mira Tessa… if anyone can hear this — we're under the sands of Khepri, in an old probe.",
	"Tu komandor Aris Varn": "This is Commander Aris Varn",
	"Tu komandor Aris Varn. Rój zjada moich ludzi. Potrzebuję was — choć nie jest mi to w smak.": "This is Commander Aris Varn. The Swarm is devouring my people. I need you — though I don't like it.",
	"Tu Koss, technik kompleksu": "This is Koss, complex technician",
	"Tu Koss, technik kompleksu. Jest nas sześcioro, pracujemy pod przymusem. Zanim cokolwiek zniszczycie… pomyślcie o nas.": "This is Koss, complex technician. There are six of us, working under duress. Before you destroy anything… think of us.",
	"Tu Koss, technik kompleksu… pracujemy pod przymusem": "This is Koss, complex technician… we work under duress",
	"Tu Koss, technik kompleksu… pracujemy pod przymusem. Ta instalacja wysysa energię całej planety.": "This is Koss, complex technician… we work under duress. This installation drains the energy of the entire planet.",
	"Tu Lira, Stacja Ciszy na Eos": "This is Lira, Silence Station on Eos",
	"Tu Lira, Stacja Ciszy na Eos. Nadajnik ma jeszcze kilka godzin zasilania. Potrzebuję dowódcy.": "This is Lira, Silence Station on Eos. The transmitter has only a few hours of power left. I need a commander.",
	"Tu Tessa… jeśli ktoś to słyszy: czworo z nas przeżyło": "This is Tessa… if anyone can hear this: four of us survived",
	"Tu Tessa… jeśli ktoś to słyszy: czworo z nas przeżyło. Nie przejdziemy pieszo przez jamy.": "This is Tessa… if anyone can hear this: four of us survived. We can't cross the pits on foot.",
	"Tu Varn": "Varn here",
	"Tu Varn. Nie przepadam za Koloniami, ale Rój zjada moich ludzi. Ze Szczytu w centrum przełęczy zagłuszymy ich rezonans.": "Varn here. I'm no fan of the Colonies, but the Swarm is devouring my people. From the Summit at the centre of the pass we'll jam their resonance.",
	"Tu Vok": "Vok here",
	"Tu Vok. Dość. Mam dla was propozycję — wysłuchajcie jej, zanim strzelicie.": "Vok here. Enough. I have a proposal for you — hear it out before you fire.",
	"TURBINA": "TURBINE",
