	"Turret": "Turret",
	"Twierdza": "Fortress",
	"TWIERDZA": "FORTRESS",
	"Twierdza Admiralicji pada, a Vok ucieka na orbitę z resztą floty": "The Admiralty Fortress falls, and Vok flees to orbit with the rest of her fleet",
	"Twierdza Admiralicji pada, a Vok ucieka na orbitę z resztą floty.": "The Admiralty Fortress falls, and Vok flees to orbit with the rest of her fleet.",
	"Twierdza Admiralicji w zasięgu wzroku": "The Admiralty fortress is in sight",
	"Twierdza Admiralicji w zasięgu wzroku. Wieże, bateria przeciwlotnicza i osłony doktryny — nie atakujmy jej bez uplinku.": "The Admiralty fortress is in sight. Towers, a Flak Battery and doctrine shields — let's not attack it without the uplink.",
	"Twierdza gotowa: centrum o 50% wytrzymalsze, +4 metalu/s": "Fortress ready: centre 50% tougher, +4 metal/s",
	"Twierdza gotowa: centrum o 50% wytrzymalsze, +4 metalu/s. Wybierz doktrynę w BADANIACH.": "Fortress ready: centre 50% tougher, +4 metal/s. Choose a doctrine in RESEARCH.",
