	"Uderzenie orbitalne i szturm na umocnioną bazę": "Orbital strikes and an assault on a fortified base",
	"uderzenie orbitalne w wybrany obszar co 100 s. Wymaga Kolonii; 40 mocy.": "orbital strike on a chosen area every 100 s. Requires Colony; 40 power.",
	"uderzenie orbitalne w zbadany punkt — po 3 s 420 obrażeń w promieniu 110 (słabnących ku brzegom), odnowienie 100 s. Wymaga Kolonii; 40 mocy.": "orbital strike on an explored point — after 3 s, 420 damage within 110 (falling off towards the edges), cooldown 100 s. Requires Colony; 40 power.",
	"Uderzenie z orbity": "Orbital strike",
