	"Uderzenie z orbity wymaga panowania na orbicie": "An orbital strike requires control of the orbit",
	"Uderzenie z orbity wymaga panowania na orbicie.": "An orbital strike requires control of the orbit.",
	"Uderzenie z orbity: wskaż cel (LPM)": "Orbital strike: pick a target (LMB)",
	"Uderzenie z orbity: wskaż cel (LPM). PPM lub Esc — anuluj.": "Orbital strike: pick a target (LMB). RMB or Esc — cancel.",
	"Uderzenie z uplinku pali zapasy Admiralicji (500 metalu mniej), a w rozdziale XIII Vok ma mniej kapsuł (około jednej trzeciej), uderzenie z orbity ładuje się o jedną trzecią dłużej, a jej kwatera jest o 25% słabsza": "The uplink strike burns the Admiralty's supplies (500 metal less), and in chapter XIII Vok has fewer pods (about a third), her orbital strike charges a third longer, and her headquarters is 25% weaker",
	"Uderzenie z uplinku pali zapasy Admiralicji (500 metalu mniej), a w rozdziale XIII Vok ma mniej kapsuł (około jednej trzeciej), uderzenie z orbity ładuje się o jedną trzecią dłużej, a jej kwatera jest o 25% słabsza. Garnizon Varna zostaje sam.": "The uplink strike burns the Admiralty's supplies (500 metal less), and in chapter XIII Vok has fewer pods (about a third), her orbital strike charges a third longer, and her headquarters is 25% weaker. Varn's garrison is left alone.",
	"Uderzenie z uplinku spaliło stocznię Admiralicji: flota, którą Vok zbiera pod pierścieniami Glacjalis, będzie słabsza": "The uplink strike burned the Admiralty shipyard: the fleet Vok is gathering beneath the Rings of Glacialis will be weaker",
	"Uderzenie z uplinku spaliło stocznię Admiralicji: flota, którą Vok zbiera pod pierścieniami Glacjalis, będzie słabsza. Garnizon Varna milczy.": "The uplink strike burned the Admiralty shipyard: the fleet Vok is gathering beneath the Rings of Glacialis will be weaker. Varn's garrison is silent.",
	"Udostępnia badania pogody, napędów, celowania i energetyki": "Enables weather, drive, targeting and energy research",
	"Udostępnia badania pogody, napędów, celowania i energetyki. Pobór: 30 mocy.": "Enables weather, drive, targeting and energy research. Draw: 30 power.",
