	"Ukryci": "Hidden",
	"Ukryci do wykrycia · PPM na wrogim budynku: sabotaż": "Hidden until detected · RMB on an enemy building: sabotage",
	"Ukryci, dopóki w promieniu 150 nie ma wrogiej jednostki (budynki ich nie wykrywają)": "Hidden until an enemy unit is within 150 (buildings cannot detect them)",
	"Ukryci, dopóki w promieniu 150 nie ma wrogiej jednostki (budynki ich nie wykrywają). PPM na wrogim budynku: podłożenie ładunku (4 s) wyłącza go na 25 s; centrum — także opóźnia desant o 15 s. Ładunek odnawia się 45 s. Słabi w walce: strzelają tylko na rozkaz. Wymaga Kolonii.": "Hidden until an enemy unit is within 150 (buildings cannot detect them). RMB on an enemy building: planting a charge (4 s) disables it for 25 s; on a centre — it also delays the landing by 15 s. The charge recharges in 45 s. Weak in combat: they fire only on command. Requires Colony.",
