	"UPADEK HEFAJSTOSA": "THE FALL OF HEPHAESTUS",
	"UPADŁA": "FALLEN",
	"Uplink działa": "The uplink is working",
	"Uplink działa. Varn wzywa pomocy: jego garnizon na wschodnim grzbiecie otoczyli Wartownicy. Ten sam uplink może jednak uderzyć w stocznię Admiralicji, zanim Vok zwoduje nowe okręty. Decyzja zmienia rozdział XIII.": "The uplink is working. Varn calls for help: the Wardens have surrounded his garrison on the eastern ridge. But the same uplink could strike the Admiralty shipyard before Vok launches new ships. The decision changes chapter XIII.",
	"Uplink trafił w stocznię Admiralicji": "The uplink hit the Admiralty shipyard",
	"Uplink trafił w stocznię Admiralicji. Ich zapasy płoną — a flota Vok straci okręty, zanim zdąży je zwodować.": "The uplink hit the Admiralty shipyard. Their stores are burning — and Vok's fleet will lose ships before it can launch them.",
	"Uratowani technicy byli ludźmi Dominium, zmuszonymi do pracy w kompleksie — zostali z Koloniami": "The rescued technicians were Dominion people forced to work in the complex — they stayed with the Colonies",
	"Uratowani technicy byli ludźmi Dominium, zmuszonymi do pracy w kompleksie — zostali z Koloniami. Varn spłaca dług: Twoja fabryka buduje niszczyciele czołgów Dominium, w rozdziale VIII jego baza ma posiłki (2 niszczyciele i bastion), a w IX dołącza do Ciebie eskorta 2 niszczycieli.": "The rescued technicians were Dominion people forced to work in the complex — they stayed with the Colonies. Varn repays the debt: your factory builds Dominion Tank Destroyers, in chapter VIII his base gets reinforcements (2 destroyers and a bastion), and in IX an escort of 2 destroyers joins you.",
