	"V · Ostatni konwój": "V · The Last Convoy",
	"Varn czeka na nich na Nivalis — wciąż z dystansem": "Varn waits for them on Nivalis — still keeping his distance",
	"Varn czeka na nich na Nivalis — wciąż z dystansem.": "Varn waits for them on Nivalis — still keeping his distance.",
	"Varn i Lira lecą ramię w ramię": "Varn and Lira fly side by side",
	"Varn i Lira lecą ramię w ramię. Wspólne dowództwo przetrwało bitwę — na pograniczu zapada rozejm.": "Varn and Lira fly side by side. The joint command survived the battle — a truce settles over the Frontier.",
	"Varn i Lira podpisują rozejm na całym pograniczu.": "Varn and Lira sign a truce across the whole Frontier.",
	"Varn leci obok Liry": "Varn flies beside Lira",
