	"Wartownicy atakują często średnimi grupami, iskry skaczą na Twoje roboty, strażnicy wchodzą w fazę i scalają się w konstrukty; przegrany atak wycofują.": "The Wardens attack often in medium groups, Sparks blink onto your robots, Wardens phase and merge into Constructs; they pull back failing attacks.",
