	"Wejście w atmosferę": "Atmospheric entry",
	"Wejście w atmosferę. Pod nami kotlina Eos — i garnizon Dominium przy stacjach łączności.": "Atmospheric entry. Below us lies the Eos basin — and the Dominion garrison by the communication stations.",
	"wersja": "version",
	"Wersja 0": "Version 0",
	"Wersja 0.11 · proceduralna muzyka i dźwięk · M: wyciszenie": "Version 0.11 · procedural music and sound · M: mute",
	"WEZWANIE VARNA": "VARN'S CALL",
	"Węzeł Nadir odzyskany": "The Nadir node is reclaimed",
	"Węzeł Nadir odzyskany. Lira uruchamia sieć, latarnie rozbłyskują jedna po drugiej, a transporty pomocy ruszają ku Koloniom. Nadszedł Odzyskany Świt.": "The Nadir node is reclaimed. Lira brings the network online, the beacons flare up one after another, and relief transports head for the Colonies. Reclaimed Dawn has come.",
	"Węzły są nasze": "The nodes are ours",
	"Węzły są nasze. Kompleks czeka na rozkaz: zniszczyć czy odłączyć?": "The nodes are ours. The complex awaits orders: destroy or disconnect?",
	"Węzły sterujące są w Twoich rękach": "The control nodes are in your hands",
	"Węzły sterujące są w Twoich rękach. Tej decyzji nie można cofnąć; zmienia przebieg misji, premię i epilog.": "The control nodes are in your hands. This decision cannot be undone; it changes the course of the mission, the bonus and the epilogue.",
	"Wheel_": "Wheel_",
	"Wiadomości": "Messages",
	"Wiadomość": "Message",
	"Wiadomość do:": "Message to:",
	"Wiązka narasta na jednym celu · wielka kuźnia": "Beam builds up on a single target · great forge",
	"wiązka narasta, dopóki trzyma ten sam cel — każde trafienie +25%, do ×2,5. Zmiana celu zeruje wiązkę; najlepszy przeciw ciężkim pojazdom i budynkom.": "the beam builds up while it holds the same target — each hit +25%, up to ×2.5. Switching targets resets the beam; best against heavy vehicles and buildings.",
	"wiązka, której obrażenia rosną o 25% z każdym kolejnym trafieniem tego samego celu (do +150%).": "a beam whose damage grows by 25% with each consecutive hit on the same target (up to +150%).",
	"WIDOK TAKTYCZNY": "TACTICAL VIEW",
	"Widzę wasze kadłuby": "I see your hulls",
	"Widzę wasze kadłuby. Eskadry — ognia.": "I see your hulls. Squadrons — fire.",
	"Widzimy was! Czworo badaczy, bez broni": "We see you! Four researchers, unarmed",
	"Widzimy was! Czworo badaczy, bez broni. Archiwum sondy jest na południowym wschodzie — tylko jedno z nas potrafi je odczytać na miejscu.": "We see you! Four researchers, unarmed. The probe archive is to the south-east — only one of us can read it on site.",
	"Wieczna noc": "Eternal night",
	"Wieczny dzień": "Eternal day",
	"Wielka Kuźnia": "Great Forge",
	"Wiemy od jeńców, gdzie Dominium oszczędza na pancerzu": "The prisoners told us where the Dominion skimps on armour",
	"Wiemy od jeńców, gdzie Dominium oszczędza na pancerzu. A orbita ma dla nas dwa zrzuty posiłków.": "The prisoners told us where the Dominion skimps on armour. And orbit has two reinforcement drops for us.",
	"Wieża echa": "Echo Tower",
	"wieże i budynki Dominium w rozdziałach IV–VI mają o 10% mniej wytrzymałości (najwięcej znaczy to w kompleksie Hefajstos), a posiłki z orbity mogą nadejść dwa razy.": "Dominion towers and buildings in chapters IV–VI have 10% less HP (this matters most in the Hephaestus Complex), and reinforcements from orbit can arrive twice.",
	"Wieżyczka": "Turret",
