	"Wolne Kolonie: Odzyskany Świt. Ekspedycja ląduje przy opuszczonej stacji. Przywróć łączność, uruchom reaktor i laboratorium, a następnie usuń garnizon Dominium.": "Free Colonies: Reclaimed Dawn. The expedition lands by an abandoned station. Restore communications, bring a Reactor and Laboratory online, then remove the Dominion garrison.",
