	"Wszystkie szczeliny prowadzą do Bramy przy czarnej dziurze Erebus": "Every rift leads to the Gate by the black hole Erebus",
	"Wszystkie szczeliny prowadzą do Bramy przy czarnej dziurze Erebus. Tam rozstrzygnie się ta wojna.": "Every rift leads to the Gate by the black hole Erebus. That is where this war will be decided.",
	"Wszystkie szczeliny prowadzą tutaj — do Bramy przy horyzoncie Erebusa": "All the rifts lead here — to the Gate at the horizon of Erebus",
	"Wszystkie szczeliny prowadzą tutaj — do Bramy przy horyzoncie Erebusa.": "All the rifts lead here — to the Gate at the horizon of Erebus.",
	"Wszystkie szczeliny prowadzą w jedno miejsce: do Bramy przy horyzoncie zdarzeń czarnej dziury Erebus": "All the rifts lead to one place: the Gate at the event horizon of the Erebus black hole",
	"Wszystkie szczeliny prowadzą w jedno miejsce: do Bramy przy horyzoncie zdarzeń czarnej dziury Erebus. Trzy szczeliny osłaniają ją i wypuszczają kolejne okręty Wartowników. Zamknij je — a potem zniszcz Bramę, zanim przejdzie przez nią więcej maszyn. Kto poleci z Tobą, zależy od decyzji podjętych w tym akcie.": "All the rifts lead to one place: the Gate at the event horizon of the Erebus black hole. Three rifts shield it and release more Warden ships. Close them — then destroy the Gate before more machines come through. Who flies with you depends on the decisions made in this act.",
	"Wszystkie szczeliny zamknięte — Brama odsłonięta! Cała flota: ognia!": "All rifts sealed — the Gate is exposed! Whole fleet: fire!",
	"Wszystkie trzy rdzenie dotarły — Vale nie stracił żadnego wozu": "All three cores arrived — Vale didn't lose a single vehicle",
