	"Wulkaniczny świat przecięty dwiema rzekami lawy": "A volcanic world cut by two rivers of lava",
	"Wulkaniczny świat przecięty dwiema rzekami lawy. Bazaltowe przeprawy są jedynymi drogami do centralnej kaldery z najbogatszymi złożami. Obsydianowe iglice osłaniają piechotę, a lawa rozświetla noc.": "A volcanic world cut by two rivers of lava. Basalt crossings are the only routes to the central caldera with the richest deposits. Obsidian spires shelter infantry, and the lava lights up the night.",
