	"Z kompleksu zostaje krater i opadający popiół. Planeta oddycha — ale Dominium straciło elektrownię i nie zapomni.": "All that remains is a crater and falling ash. The planet breathes — but the Dominion has lost a power plant and will not forget.",
	"z krawędzi mapy nadchodzą coraz większe i silniejsze fale (czołgi od 3., ciężkie maszyny od 6., lotnictwo od 8., artyleria od 10. fali). Gra kończy się utratą centrum; liczy się czas i liczba fal, a najlepszy wynik na każdej mapie i poziomie jest zapamiętywany. Liczba graczy i rodzaj przeciwnika nie mają znaczenia.": "ever larger and stronger waves come from the edges of the map (tanks from wave 3, Heavy Walkers from wave 6, aircraft from wave 8, artillery from wave 10). The game ends when you lose your centre; time and waves survived count, and the best result on every map and difficulty is recorded. The number of players and the type of opponent do not matter.",
