	"Zagłuszony rezonans pokazał, skąd Rój czerpie siłę: z Serca pod magmą Pyrrhosa": "The jammed resonance revealed where the Swarm draws its strength: from the Heart beneath the magma of Pyrrhos",
	"Zagłuszony rezonans pokazał, skąd Rój czerpie siłę: z Serca pod magmą Pyrrhosa.": "The jammed resonance revealed where the Swarm draws its strength: from the Heart beneath the magma of Pyrrhos.",
	"Zagłuszony Rój cofnął się do źródła: Serca bijącego pod rzekami magmy Pyrrhosa": "The jammed Swarm has retreated to its source: the Heart beating beneath the magma rivers of Pyrrhos",
	"Zagłuszony Rój cofnął się do źródła: Serca bijącego pod rzekami magmy Pyrrhosa. Varn przekazuje Koloniom dostęp do stacji orbitalnej. To ostatnia bitwa aktu — zniszcz Serce, zanim Rój obudzi się na dobre.": "The jammed Swarm has retreated to its source: the Heart beating beneath the magma rivers of Pyrrhos. Varn grants the Colonies access to an Orbital Uplink. This is the act's final battle — destroy the Heart before the Swarm fully awakens.",
