	"Załóż przyczółek (2 przekaźniki), potem zniszcz bazę Admiralicji. Dodatkowo: najwyżej 1 zestrzelona kapsuła.": "Establish a foothold (2 relays), then destroy the Admiralty base. Bonus: no more than 1 pod shot down.",
