	"Zamarznięta placówka badawcza Nivalis": "The frozen research outpost of Nivalis",
	"Zamarznięta placówka badawcza Nivalis. Ruiny modułów w centrum otaczają szczeliny lodowca z dwoma mostami, a ściany zamrożonych narośli i kokonów zdradzają, że coś tu przetrwało zimę. Rogacze lodowe krążą między ruinami.": "The frozen research outpost of Nivalis. Ruined modules at the centre are ringed by glacier crevasses spanned by two bridges, and walls of frozen growths and cocoons betray that something survived the winter here. Ice Stags roam among the ruins.",
