	"Złote wydmy Helionu pod palącym słońcem. Środkiem mapy biegnie kanion między ścianami skalnymi z przejściami na różnych wysokościach; na jego dnie leżą oazy i najbogatsze złoża. Na flankach sypkie grzbiety wydm, w piasku czają się paszczaki.": "The golden dunes of Helion under a scorching sun. A canyon runs through the middle of the map between rock walls, with passages at different heights; oases and the richest deposits lie on its floor. Loose dune ridges on the flanks, with Dune Maws lurking in the sand.",
