	"Zniszczone pojazdy i budynki zostawiają wraki warte 25% kosztu (15–140 metalu, znikają po 4 min). PPM robotem na wraku: rozbiórka 3 s i dowóz złomu na plac. Po dostawie robot sam szuka kolejnego wraku w pobliżu placu. Pobór 5 mocy.": "Destroyed vehicles and buildings leave wrecks worth 25% of their cost (15–140 metal, vanish after 4 min). RMB with a robot on a wreck: 3 s dismantling and scrap delivery to the yard. After delivery the robot looks for the next wreck near the yard. Draws 5 power.",
